// Generated by npm run gen:packs. Edit public/data.js instead.
AF_ADD_PACK("AB", [{"id":"aish","needsPractitioner":true,"name":"Assured Income for the Severely Handicapped (AISH)","level":"Alberta","category":"Money","amount":"Monthly living allowance + health and personal benefits","summary":"Alberta disability income assistance for people whose permanent disability prevents employment.","requires":["aishAge","ab","citizenPR","aishMedical","aishFinancial" ],"note":"AISH is for a severe, permanent disability that prevents employment. Alberta now uses one application to assess both AISH and ADAP — submit it once, not separately for each program.","applyText":"Apply for Alberta disability income assistance","applyUrl":"https://www.alberta.ca/how-to-apply-for-aish-and-adap","source":"https://www.alberta.ca/aish-eligibility","detail":{"about":"AISH is Alberta disability income assistance for adults whose severe, permanent disability prevents employment. It includes a monthly living allowance and may include health and personal benefits.","steps":["Use Alberta's combined AISH/ADAP application — it assesses which program fits; you do not make two separate applications.","Complete your part and arrange the required medical report with a medical professional registered in Alberta.","Submit online, or use the application options Alberta Supports provides if online is not workable for you." ],"documents":["Medical report showing how a severe, permanent impairment prevents employment","Proof of Alberta residency + Canadian citizenship / PR","Financial details (income and assets)","Disability Income Assistance (DIA) application form, if you cannot apply online","Disability Assistance Medical Report, completed by your health professional" ],"tips":["The medical form should focus on how your condition permanently prevents employment, not just the diagnosis.","The combined application assesses AISH and ADAP. Alberta, not this tool, decides the program and benefit amount.","Use Alberta's AISH/ADAP benefit estimator for a household-specific estimate before relying on any amount.","If you receive AISH or ADAP, report the outcome of your CDB and/or DTC application to Alberta, including the approved CDB amount or a denial. Alberta says that when no CDB decision had been made by February 28, 2026, $200 was reduced from April 2026 benefits.","Getting help with the online application: phone the Alberta Supports Contact Centre at 1-877-644-9992, or 780-644-9992 in Edmonton.","Your health professional may charge you a fee to complete the Disability Assistance Medical Report, and you are responsible for paying it. If you are on Income Support that cost may be covered — ask your Income Support worker. For AISH clients who transitioned to ADAP and later choose to be assessed for AISH, Alberta says it will cover the cost of one Disability Income Assistance Medical Report; this support is not time-limited.","Benefits are backdated to the month AISH or ADAP received all of the information needed to approve your application, so sending every document sooner can mean an earlier start date for your benefits.","To check where your application is, phone 587-759-6810 in the Edmonton area, or 1-877-759-6810 toll free within Alberta.","If you leave AISH or ADAP, your file may be reopened quickly if it has been less than 2 years since you got your last AISH benefits and you did not leave AISH or ADAP due to a change in your medical condition. Contact AISH or ADAP if this applies to you; if not, you will need to reapply." ],"time":"Ask Alberta Supports for the current processing time.","phone":"DIA Application Processing Centre (applications and status): 1-877-759-6810"}},{"id":"adap","needsPractitioner":true,"name":"Alberta Disability Assistance Program (ADAP)","level":"Alberta","category":"Money","amount":"Up to $1,740/month + health, personal and employment benefits","summary":"Alberta disability income assistance when a severe disability significantly impedes employment, continuously or episodically, but does not prevent it.","requires":["adapAge","ab","citizenPR","adapMedical","adapFinancial" ],"note":"The same combined application assesses ADAP and AISH. This guide can only flag that ADAP may be worth asking about — Alberta makes the eligibility decision.","applyText":"Apply for Alberta disability income assistance","applyUrl":"https://www.alberta.ca/how-to-apply-for-aish-and-adap","source":"https://www.alberta.ca/alberta-disability-assistance-program","detail":{"about":"ADAP is Alberta disability income assistance for adults whose severe disability significantly impedes employment continuously or episodically. To be medically eligible, the severe disability must be determined to significantly restrict but not prevent a person from being employed. It can include a core monthly financial benefit, health benefits, personal benefits and employment supports.","steps":["Use Alberta's combined AISH/ADAP application — it assesses which program fits; you do not make two separate applications.","Complete your part and arrange the required medical report with a medical professional registered in Alberta.","Provide the residency, status and financial information requested by Alberta Supports." ],"documents":["Medical report describing how the disability significantly impedes employment","Proof of Alberta residency + Canadian citizenship / PR","Financial details (income and assets)","Disability Income Assistance (DIA) application form, if you cannot apply online","Disability Assistance Medical Report, completed by your health professional" ],"tips":["Describe functional limits and fluctuating or episodic barriers — not only your diagnosis name.","One application is enough: Alberta decides whether AISH or ADAP is the appropriate program.","Use Alberta's AISH/ADAP benefit estimator for a household-specific estimate before relying on any amount.","If you receive ADAP or AISH, report the outcome of your CDB and/or DTC application to Alberta, including the approved CDB amount or a denial. Alberta says that when no CDB decision had been made by February 28, 2026, $200 was reduced from April 2026 benefits.","Getting help with the online application: phone the Alberta Supports Contact Centre at 1-877-644-9992, or 780-644-9992 in Edmonton.","Your health professional may charge you a fee to complete the Disability Assistance Medical Report, and you are responsible for paying it. If you are on Income Support that cost may be covered — ask your Income Support worker. For AISH clients who transitioned to ADAP and later choose to be assessed for AISH, Alberta says it will cover the cost of one Disability Income Assistance Medical Report; this support is not time-limited.","Benefits are backdated to the month AISH or ADAP received all of the information needed to approve your application, so sending every document sooner can mean an earlier start date for your benefits.","To check where your application is, phone 587-759-6810 in the Edmonton area, or 1-877-759-6810 toll free within Alberta.","If you leave AISH or ADAP, your file may be reopened quickly if it has been less than 2 years since you got your last AISH benefits and you did not leave AISH or ADAP due to a change in your medical condition. Contact AISH or ADAP if this applies to you; if not, you will need to reapply." ],"time":"Ask Alberta Supports for the current processing time.","phone":"DIA Application Processing Centre (applications and status): 1-877-759-6810"}},{"id":"aadl","name":"Alberta Aids to Daily Living (AADL)","level":"Alberta","category":"Health & equipment","amount":"Funding for medical equipment & supplies (you pay a small share)","summary":"Helps pay for equipment and supplies you need for a long-term illness, disability or condition — wheelchairs, hearing aids, breathing supplies and much more.","requires":["ab","equipmentNeed","ahcipRegistered","aadlAssessment","aadlOtherPayer" ],"note":"Covers a wide range of devices. You usually pay 25% (capped per year). Low-income households can have that waived.","applyText":"Open the official page on alberta.ca","applyUrl":"https://www.alberta.ca/alberta-aids-to-daily-living","source":"https://www.alberta.ca/aadl-eligibility-and-application-for-benefits","detail":{"about":"A provincial program that funds basic medical equipment and supplies for Albertans with a long-term disability, chronic illness or terminal illness — mobility aids, hearing aids, vision aids, breathing equipment, diabetic and ostomy supplies, and more.","steps":["See an AADL-authorized health professional (e.g. an OT, audiologist, or specialist) who assesses what you need.","They complete the authorization for the specific equipment.","Get the item from an approved vendor; AADL covers its share directly." ],"documents":["Alberta Health Care (personal health) number","An assessment from an authorized professional for the specific item" ],"tips":["You don't apply to a general office. You go through an authorizer (often an OT, physio, or audiologist). Ask your doctor for a referral.","The 25% cost-share is capped each year. Low-income Albertans and people receiving income assistance do not pay it." ],"time":"Depends on the assessment and vendor.","phone":"AADL: 780-427-0731 (toll-free via 310-0000)"}},{"id":"pdd","name":"Persons with Developmental Disabilities (PDD)","level":"Alberta","category":"Daily living supports","amount":"Funded support services (not a cash payment)","summary":"Support services for adults with a developmental disability — help with daily living, community involvement, and employment.","requires":["age18plus","ab","developmental","pddEligibility" ],"note":"For adults whose developmental disability began before age 18 and significantly affects daily living. Provides services and supports, not direct cash.","applyText":"Open the official page on alberta.ca","applyUrl":"https://www.alberta.ca/persons-with-developmental-disabilities-pdd","source":"https://www.alberta.ca/persons-with-developmental-disabilities-pdd","detail":{"about":"A program that funds services helping adults with developmental disabilities live as independently as possible — community access, home living supports, employment supports and specialized services.","steps":["Contact a PDD office or Alberta Supports to start.","An assessment confirms eligibility (developmental disability with onset before 18).","Work with a coordinator to build a support plan and connect with service providers." ],"documents":["Psychological assessment showing a developmental disability before age 18","Proof of Alberta residency + age 18+" ],"tips":["PDD funds services and supports. It does not pay you cash. Many people also receive AISH at the same time.","Start early. Assessment and planning can take time." ],"time":"Varies; assessment-based.","phone":"Alberta Supports: 1-877-644-9992"}},{"id":"fscd","name":"Family Support for Children with Disabilities (FSCD)","level":"Alberta","category":"Family supports","amount":"Services + funding for families raising a child with a disability","summary":"Support and funding for Alberta families raising a child under 18 with a disability — respite, aids, counselling, and reimbursement of some costs.","requires":["child","ab","fscdEligibility" ],"note":"Wide-ranging support for families: respite care, specialized services, and help with some out-of-pocket disability costs. It is separate from the federal Child Disability Benefit, and you can get both.","applyText":"Open the official page on alberta.ca","applyUrl":"https://www.alberta.ca/fscd","source":"https://www.alberta.ca/fscd-eligibility","detail":{"about":"A provincial program that helps families of children under 18 with disabilities cover the extra costs and stress of caregiving — respite, child-focused supports, family counselling, and reimbursement of some disability-related expenses.","steps":["Contact an FSCD office or Alberta Supports.","Meet with an FSCD worker to identify your family's needs.","A signed agreement sets out the services and funding you'll receive." ],"documents":["Medical documentation confirming your child has a disability or is awaiting a diagnosis","Proof of Alberta residency" ],"tips":["Ask specifically about respite.","You can receive FSCD and the federal Child Disability Benefit at the same time." ],"time":"Assessment-based; contact them to begin.","phone":"Alberta Supports: 1-877-644-9992"}},{"id":"dres","name":"Disability Related Employment Supports (DRES)","level":"Alberta","category":"Employment","amount":"Potential funding for approved disability-related accommodations","summary":"May fund approved accommodations for an Albertan who is employed or heading into employment. Their documented permanent or long-term disability must create a barrier to education, training, or employment.","requires":["age16plus","ab","disabilityDoc","dresResidencyAndStatus","dresDisabilityBarrier","dresEmploymentRoute" ],"eligibility":{"mode":"all","items":["You are 16 or older.","You reside in Alberta.","You are legally entitled to work or train in Canada.","You are a Canadian citizen, permanent resident, or Convention Refugee.","You are employed or employment destined.","You may be eligible for funding if you have a disability that is documented permanent or long-term and creating a barrier to education, training and/or employment." ]},"requiresNote":"You must be 16 or older, reside in Alberta, be legally entitled to work or train in Canada, and be a Canadian citizen, permanent resident, or Convention Refugee. You must be employed or employment destined. You may be eligible for funding if your disability is documented permanent or long-term and creating a barrier to education, training and/or employment.","note":"Alberta's published examples include: assistive devices, equipment or technology; ASL interpreting and captioning; an academic aide or note taker; communication or hearing devices for work; workplace access or changes; and work-related vehicle changes. Education or training supports are not available while you attend Alberta Education-funded K–12 or a publicly funded Alberta post-secondary institution. Contact the school or institution for disability accommodations. A separate eligible work route may still be considered.","applyText":"Open the official page on alberta.ca","applyUrl":"https://www.alberta.ca/disability-related-employment-supports","source":"https://www.alberta.ca/disability-related-employment-supports","detail":{"about":"DRES may fund approved accommodations that address a documented permanent or long-term disability barrier for an employed or employment-destined person. Published examples are assistive devices, equipment or technology; ASL interpreting and captioning; an academic aide or note taker; communication or hearing devices for work; workplace access or modification; and work-related vehicle modifications. It does not fund medical treatments or therapies, daily-living items, job matching, employment and skills training, or wage subsidies.","steps":["Open the official DRES page and use its current contact route to ask about an employment or employment-destined accommodation.","Confirm the Alberta residency, age, legal entitlement, immigration-status, disability-duration, disability-barrier and employment-route criteria.","Describe the disability-related barrier and the specific accommodation requested, using only the current DRES coverage rules." ],"documents":["Documentation that the disability is permanent or long-term and creates a barrier to education, training or employment","Information confirming Alberta residency and legal entitlement to work or train in Canada","Information confirming Canadian citizen, permanent resident or Convention Refugee status","Information showing that you are employed or employment destined and identifying the requested accommodation" ],"tips":["Alberta's published examples of what is covered include: assistive devices, equipment or technology; ASL interpreting and captioning; an academic aide or note taker; communication or hearing devices for work; workplace access or changes; and work-related vehicle changes.","If the request is for education or training while you attend Alberta Education-funded K–12 or a publicly funded Alberta post-secondary institution, contact the school or institution for disability accommodations. This does not by itself rule out a separate eligible work route." ],"phone":"Alberta Supports Contact Centre 780-644-9992 or 1-877-644-9992"}},{"id":"ab-grant-disability","name":"Alberta Grant for Students with Disabilities","level":"Alberta","category":"Education","amount":"Up to $3,000 per loan year for approved costs after federal funding","summary":"May fund approved disability-related services and equipment when the federal services-and-equipment grant is unavailable or does not cover all approved costs; federal funding is allocated first.","requires":["student","ab","disabilityDoc","abGrantStudyAidEligibility","abGrantCurrentCostRequest" ],"note":"You need Alberta student-funding eligibility, at least $1 of Alberta calculated need, and a full-time course load of at least 60% (or a documented reduced load of at least 40%). The provincial amount cannot exceed approved service and equipment costs left after federal-first allocation.","applyText":"Apply through Alberta Student Aid","applyUrl":(a) => STUDENT_AID[a.province] || FED_STUDENT_AID,"source":"https://studentaid.alberta.ca/policy/student-aid-policy-manual/eligibility-for-student-loans-and-grants/alberta-student-grants/","detail":{"about":"A provincial grant for approved disability-related services and equipment. The Canada Student Grant for Services and Equipment – Students with Disabilities is allocated first. Alberta funding may apply only when that federal grant is unavailable or leaves approved costs uncovered. The Alberta maximum is $3,000 per loan year and cannot exceed approved costs.","aboutList":{"lead":"A provincial grant for approved disability-related services and equipment.","items":["The Canada Student Grant for Services and Equipment – Students with Disabilities is allocated first.","Alberta funding may apply only when that federal grant is unavailable or leaves approved costs uncovered.","The Alberta maximum is $3,000 per loan year and cannot exceed approved costs." ]},"steps":["Apply for financial assistance through Alberta Student Aid and request disability-related services or equipment.","For each new financial-assistance application where disability-related services or equipment are requested, complete the current Schedule 4 with the services and equipment requested and their current costs.","Attach quotes or estimates for every requested cost and include documentation describing why the items are needed if Alberta Student Aid does not already have it.","Submit receipts by the end of the study period and return any unused or undocumented funding to avoid an overpayment." ],"documents":["An approved Schedule 4 for the current financial-assistance application","Current quotes or estimates showing the requested service and equipment costs","Documentation of a permanent disability or persistent or prolonged disability","Documentation describing the disability-related need for each service or item, if not previously provided","Receipts for funded services and equipment, due by the end of the study period" ],"tips":["Disability-type verification already on file may sometimes be reusable, but every new application requesting services or equipment still needs a current Schedule 4 cost request and quotes or estimates.","Ask your school's disability services office to help describe the need and prepare Schedule 4, but confirm all requested costs are current.","Keep copies of approvals, quotes, invoices and receipts. Unused funding, or funding without required receipts, must be returned or becomes an overpayment." ],"time":"Assessed with your Alberta student aid application.","phone":"Alberta Student Aid Service Centre: 1-855-606-2096"}},{"id":"adult-health-benefit","name":"Alberta Adult Health Benefit","level":"Alberta","category":"Health","amount":"Dental care, prescription drugs, eye exams and glasses, and more — ask your provider what is paid for","summary":"Health coverage for lower-income adults who are pregnant, have high ongoing drug needs, or are leaving Income Support or AISH because of work or CPP-D income. It covers prescriptions, dental, eye care, and essential diabetic supplies.","requires":["adult","ab","citizenPR","adultHealthIncome","adultHealthGateway" ],"note":"Helps cover the cost of medication if you're on a lower income and not already covered by AISH.","applyText":"Open the official page on alberta.ca","applyUrl":"https://www.alberta.ca/alberta-adult-health-benefit","source":"https://www.alberta.ca/alberta-adult-health-benefit","detail":{"about":"Ongoing health coverage for lower-income adults and families who qualify — prescription drugs, dental, optical, emergency ambulance, and diabetic supplies — at no monthly premium.","steps":["Check the income guidelines on the page.","Complete the Alberta Adult Health Benefit application.","Sign the consent for the Canada Revenue Agency to verify your income, add documentation of your high ongoing prescription drug needs if it applies, and submit the form by email, mail or fax." ],"documents":["Signed Consent for Canada Revenue Agency to Verify Income (part of the application form)","Alberta Health Care number","If it applies: documentation of high ongoing prescription drug needs, such as a pharmacy dispensing history report" ],"tips":["If you leave AISH or Income Support because you started working, you may keep this coverage. Ask specifically.","If your application is denied because of your income, Alberta describes a way to ask for a reassessment with extra income documents. The steps depend on when you were denied." ],"time":"A few weeks to process.","phone":"Health Benefits Contact Centre: 780-427-6848, or toll free 1-877-469-5437"}},{"id":"child-health-benefit","name":"Alberta Child Health Benefit","level":"Alberta","category":"Health (for children)","amount":"Covers eligible prescription drugs, basic and preventative dental care and eyeglasses for children in low-income households","summary":"Health coverage for children under 18 in lower-income families. There is also a conditional route for 18- and 19-year-olds still in high school through grade 12.","requires":["achbAge","ab","citizenPR","lowIncome","achbOlderDependent","achbFamilyResidencyStatus","achbCoverageCoordination" ],"note":"The applicant and family members must live in Alberta and be Canadian citizens or permanent residents. Income Support, AISH, and Non-Insured Health Benefits are excluded government coverage. Private plans are used first. They are not exclusions. For services covered by both ACHB and the Canadian Dental Care Plan, claims go to the Canadian Dental Care Plan first.","applyText":"Open the official page on alberta.ca","applyUrl":"https://www.alberta.ca/alberta-child-health-benefit","source":"https://www.alberta.ca/alberta-child-health-benefit","declarationText":"Declaration for an 18- or 19-year-old dependent (AEHB3654)","declarationUrl":"https://cfr.forms.gov.ab.ca/Form/AEHB3654","detail":{"about":"No-premium prescription, dental, optical and other eligible health coverage for children under 18 in lower-income Alberta families. A child aged 18 or 19 can qualify only while living at home and attending high school through grade 12, with declaration AEHB3654.","steps":["Check the income guidelines and confirm the whole family's Alberta residency, citizenship or permanent-resident status, and other government health coverage.","Complete the Alberta Child Health Benefit application.","For an eligible 18- or 19-year-old living at home and attending high school through grade 12, also submit Declaration of 18 and 19 Year Old Dependent AEHB3654: https://cfr.forms.gov.ab.ca/Form/AEHB3654","Submit the application with proof of income." ],"documents":["Proof of family income","Your children's Alberta Health Care numbers","Declaration AEHB3654 for an eligible 18- or 19-year-old dependent" ],"tips":["Income Support, AISH, and Non-Insured Health Benefits for First Nations and Inuit are excluded government health-benefit coverage.","Private or other health insurance is not an exclusion. Use it first. ACHB may cover remaining eligible costs.","If you also have the Canadian Dental Care Plan, claims for services covered by both plans go to the Canadian Dental Care Plan first. ACHB may then cover remaining eligible dental costs." ],"time":"A few weeks to process.","phone":"Health Benefits Contact Centre: 780-427-6848 or 1-877-469-5437"}},{"id":"ramp","needsPractitioner":true,"name":"Residential Access Modification Program (RAMP)","level":"Alberta","category":"Health & equipment","amount":"Up to $12,000 per benefit year, to a maximum of $24,000 over 10 years","summary":"Alberta grant that pays for permanent changes so you can get into and move around your own home. It is for wheelchair users of any age, seniors using a 4-wheel walker, and people living with certain progressive conditions.","requires":["ab","citizenPR","homeAccessNeed","rampMobilityRoute","rampIncomeAndResidency" ],"note":"You can apply as a homeowner, a tenant, or someone living with family. Indigenous applicants can apply whether they live on- or off-reserve. Changes must be permanent. They must be finished within 90 days of approval unless RAMP allows more time.","applyText":"Apply for RAMP","applyUrl":"https://www.alberta.ca/residential-access-modification-program","source":"https://www.alberta.ca/residential-access-modification-program","detail":{"about":"A provincial grant for permanent modifications that let you enter and move within your own living space. RAMP pays up to $12,000 per person each benefit year, which runs April 1 to March 31, and up to $24,000 per person within 10 years. You may be eligible if you are an Albertan of any age who uses a wheelchair, a senior (65+) who uses a 4-wheel walker on an ongoing basis, or living with a progressive neuro-degenerative disease including multiple sclerosis, muscular dystrophy, ALS, COPD, Parkinson's disease, Alzheimer's disease, spina bifida, spinal cord injuries or non-recovering stroke. You must be a Canadian citizen or permanent resident who has lived in Alberta for 90 continuous days, and your family income must be within the RAMP table — from $36,900 for a single adult to $94,500 for a couple with five children, plus $7,131 when a child permanently uses a wheelchair. Alberta notes that exceptions may apply when income is within $1,200 of the threshold.","aboutList":{"lead":"A provincial grant for permanent modifications that let you enter and move within your own living space.","items":["RAMP pays up to $12,000 per person each benefit year, which runs April 1 to March 31, and up to $24,000 per person within 10 years.","You may be eligible if you are an Albertan of any age who uses a wheelchair, a senior (65+) who uses a 4-wheel walker on an ongoing basis, or living with a progressive neuro-degenerative disease including multiple sclerosis, muscular dystrophy, ALS, COPD, Parkinson's disease, Alzheimer's disease, spina bifida, spinal cord injuries or non-recovering stroke.","You must be a Canadian citizen or permanent resident who has lived in Alberta for 90 continuous days, and your family income must be within the RAMP table — from $36,900 for a single adult to $94,500 for a couple with five children, plus $7,131 when a child permanently uses a wheelchair.","Alberta notes that exceptions may apply when income is within $1,200 of the threshold." ]},"steps":["Read the RAMP Guidelines and Criteria document before starting; Alberta says incomplete applications will not be processed.","Complete the RAMP Application Checklist, the RAMP Application Form and the RAMP Modification Recommendation Form.","Add any conditional forms that apply to you — Landlord Agreement, Band Council Resolution, Sponsor Income Verification, or Disclosure Consent.","Mail the complete package to RAMP, Assisted Living and Social Services, PO Box 808 Edmonton Main, Edmonton, AB T5J 2L4, or use the email address on the RAMP page." ],"documents":["RAMP Application Checklist, Application Form and Modification Recommendation Form","Proof of Canadian citizenship or permanent residence, and of 90 continuous days in Alberta","Family income verification for your household size","Any conditional form that applies: Landlord Agreement, Band Council Resolution, Sponsor Income Verification, or Disclosure Consent" ],"tips":["Tell RAMP if you are waiting for hospital discharge or are in palliative care. Alberta gives those applications priority.","Changes must be permanent. RAMP reviews requests for temporary changes case by case.","There is no appeal process. If you are refused, you can reapply with updated information.","Alberta has said the Guidelines and Criteria document and the Application Form are being updated. Use the current forms on the RAMP page until the new ones appear." ],"time":"Alberta says you should receive a decision letter in the mail within 30 days of applying."}},{"id":"parking-placard","needsPractitioner":true,"name":"Disability Parking Placard","level":"Alberta","category":"Getting around","amount":"Accessible parking permit","summary":"A placard that lets you use accessible parking spaces.","requires":["ab","abPlacardMobility","certifier" ],"note":"You may be eligible if you can't walk more than 50 metres (164 feet). You may also be eligible if a loss of vision greatly limits your safe and independent mobility in parking areas.","applyText":"Apply for a parking placard","applyUrl":"https://www.alberta.ca/get-parking-placard-people-disabilities","source":"https://www.alberta.ca/parking-placard-disabilities","detail":{"about":"A permit that lets you park in designated accessible spaces. Long-term placards are for long-term disabilities (valid 5 years); red placards are for temporary ones (3–12 months).","steps":["Get the application form and have a medical practitioner complete their section.","Take it to any registry agent (e.g. an AMA centre)." ],"documents":["Application form with the medical section completed","Government-issued ID" ],"tips":["You don't need to own a vehicle. The placard belongs to you, not a car.","A physician, occupational therapist, physiotherapist, surgeon, podiatrist, nurse practitioner or chiropractor can complete the medical section." ],"time":"Issued at the registry, often same-day.","phone":"Any Alberta registry agent"}},{"id":"ab-service-dog-id-card","name":"Alberta Service Dog Identification Card","level":"Alberta","category":"Daily living supports","amount":"No fee to apply","summary":"The provincial identification card for a qualified service dog team in Alberta. There is no fee, and the card is mailed in about two weeks.","requires":["ab","abServiceDogQualified" ],"eligibility":{"mode":"any","items":["Your service dog passed an assessment from one of Alberta's approved service dog providers.","Your service dog graduated from a program accredited by Assistance Dogs International.","Your service dog was qualified by an organization contracted by a provincial or territorial government in Canada to train or assess service dogs to standards equivalent to the Alberta Training Standard." ]},"note":"The card has an expiration date. Check it and renew before it ends. The Alberta.ca identification card page does not explain how to renew. Call the Service Dog Assessment team at 780-427-9136. In Alberta, dial 310-0000 first, before the phone number, to call toll free.","requiresNote":"Your service dog must have passed an assessment from one of Alberta's approved service dog providers, graduated from a program accredited by Assistance Dogs International, or been qualified by an organization contracted by a provincial or territorial government in Canada to train or assess service dogs to standards equivalent to the Alberta Training Standard.","applyUrl":"https://servicedogs.alberta.ca/","source":"https://www.alberta.ca/service-dog-identification-card","detail":{"about":"Each card shows the handler's name, the dog's name, photos, a validation number and an expiration date. You apply online through the Service Dogs Portal, or you can ask the Service Dog Assessment team for a form. There is no fee, and the official identification card is mailed in approximately two weeks. Alberta.ca says qualified service dog teams must have the card to ensure access to public places, and that it verifies you and your service dog have protected public access rights in Alberta. Carry it with you at all times when in public.","aboutList":{"lead":"Each card shows the handler's name, the dog's name, photos, a validation number and an expiration date.","items":["You apply online through the Service Dogs Portal, or you can ask the Service Dog Assessment team for a form.","There is no fee, and the official identification card is mailed in approximately two weeks.","Alberta.ca says qualified service dog teams must have the card to ensure access to public places, and that it verifies you and your service dog have protected public access rights in Alberta. Carry it with you at all times when in public." ]},"steps":["Make sure your dog has qualified by one of the three accepted routes: an assessment from one of Alberta's approved service dog providers, graduation from a program accredited by Assistance Dogs International, or qualification by an organization contracted by a provincial or territorial government in Canada to standards equivalent to the Alberta Training Standard","Take one photo that clearly shows you and your service dog, with no other dogs or people in it","Apply online at the Service Dogs Portal, servicedogs.alberta.ca, or contact the Service Dog Assessment team to request a form","Wait about two weeks for the card to arrive in the mail" ],"documents":["One photo showing you and your service dog clearly, submitted in PDF format","The photo must be close-up portrait format, taken from a minimum of 6 feet away, with you facing the camera and your face clear and visible","Your dog's head and your head should be at approximately the same level in the photo" ],"tips":["The photo rules are specific and easy to get wrong. Use portrait format, taken from at least six feet away. Your face must be clear and facing the camera. No other people or dogs may be in it. Your dog's head should be at roughly the same height as yours.","The photo has to go in as a PDF, not a JPEG or a phone screenshot.","If you would rather use paper, phone the Service Dog Assessment team at 780-427-9136. In Alberta, dial 310-0000 before the phone number to call toll free. Ask for a form." ],"time":"The card is mailed in approximately 2 weeks."}},{"id":"ab-capcc","name":"Community Access for People in Continuing Care (CAPCC)","level":"Alberta","category":"Daily living supports","amount":"Support from a community access coordinator and an individual service plan","summary":"Help for adults with disabilities in facility-based continuing care in Alberta. It helps you take part in your community and feel less lonely. A community access coordinator works with you on an individual service plan.","requires":["ab","adult","abCapccContinuingCareHome" ],"eligibility":{"mode":"all","items":["You are an adult Albertan under the age of 65.","You live in a type A or type B continuing care home.","You are able to actively participate in setting and following through with your goals, and to communicate your preferences." ]},"note":"Alberta.ca does not publish an application form or a cost for this program. Contact a community access coordinator directly. The program page lists them with phone numbers.","requiresNote":"You must be an adult Albertan under the age of 65, living in a type A or type B continuing care home, and able to actively participate in setting and following through with your goals and to communicate your preferences.","applyUrl":"https://www.alberta.ca/community-access-continuing-care","source":"https://www.alberta.ca/community-access-continuing-care","detail":{"about":"CAPCC helps adults with disabilities in facility-based continuing care engage with their communities to reduce loneliness and social isolation. A community access coordinator helps you develop an individual service plan built around your own interests, which can include outings with family and friends, volunteer activities, church or spiritual activities, movies and continuing education. The program page lists the community access coordinators as Revolve Home Health Ltd. at 587-971-6779, Taproot Community Support Services at 780-439-5087, Catholic Social Services at 403-967-3533, and Calgary Alternative Support Services Inc. at 403-283-0611.","aboutList":{"lead":"CAPCC helps adults with disabilities in facility-based continuing care engage with their communities to reduce loneliness and social isolation.","items":["A community access coordinator helps you develop an individual service plan built around your own interests, which can include outings with family and friends, volunteer activities, church or spiritual activities, movies and continuing education.","The program page lists the community access coordinators as Revolve Home Health Ltd. at 587-971-6779, Taproot Community Support Services at 780-439-5087, Catholic Social Services at 403-967-3533, and Calgary Alternative Support Services Inc. at 403-283-0611." ]},"steps":["Check that you are an adult Albertan under 65 living in a type A or type B continuing care home","Find your nearest community access coordinator from the list on the program page","Contact that coordinator directly, since Alberta.ca does not publish an application form for this program","Work with the coordinator to build an individual service plan around your own interests" ],"documents":["Alberta.ca does not publish a document list for this program, so ask the community access coordinator what they need" ],"tips":["This is one of the few supports aimed at isolation, not money or equipment. That is why it is easy to miss.","It is limited to type A and type B continuing care homes. Supportive living and long-term care are not listed on the program page.","The under-65 limit is unusual for a continuing care program. Confirm it before you spend time on this one." ],"time":"Alberta.ca does not publish a timeline; ask the coordinator when you contact them."}},{"id":"ab-special-needs-housing","name":"Special Needs Housing","level":"Alberta","category":"Daily living supports","amount":"Subsidized housing; no rent formula is published for this program type","summary":"Subsidized provincial housing for people with special housing needs. This includes people with developmental disabilities and people with physical challenges. There is no central application. Find a local housing provider and apply to them directly.","requires":["ab","abSpecialNeedsHousingStatus","abSpecialNeedsHousingPlacement" ],"eligibility":{"mode":"all","items":["You have special housing needs. This includes people with developmental disabilities, people with physical challenges, victims of family violence, wards of the provincial government, the hard-to-house, and any other group with special housing needs.","Your income is below the local income limits as determined by the market for your community.","You are a Canadian citizen or permanent resident, a refugee sponsored by the Government of Canada, or a privately sponsored refugee whose sponsorship has broken down. Evacuees from Ukraine with a Canada-Ukraine Authorization for Emergency Travel are eligible to apply. Some housing providers may have additional eligibility criteria." ]},"note":"Applications are not centralized. Use the Find Housing tool to see what is available. Then contact the local housing provider for their application. Income limits are set community by community. Alberta.ca does not publish a single figure. Check the limit where you live instead of assuming.","requiresNote":"Special Needs Housing is for individuals who have special housing needs, including people with developmental disabilities, people with physical challenges, victims of family violence, wards of the provincial government, the hard-to-house, and any other group with special housing needs. You must have an income below the local income limits as determined by the market for your community, and be a Canadian citizen or permanent resident, a refugee sponsored by the Government of Canada, or a privately sponsored refugee whose sponsorship has broken down. Evacuees from Ukraine with a Canada-Ukraine Authorization for Emergency Travel are eligible to apply. Some housing providers may have additional eligibility criteria.","applyUrl":"https://findhousing.alberta.ca/","source":"https://www.alberta.ca/affordable-housing-programs","detail":{"about":"Special Needs Housing is one of four provincial affordable housing program types, alongside Community Housing, Seniors apartments and Seniors Lodge. It serves individuals who have special housing needs and may include support services for residents. Applying takes three steps: use the Find Housing tool to see which options are available to meet your needs, choose a local housing provider offering a program that suits your situation, then contact that provider directly for their application. Alberta.ca states a rent formula for Community Housing (30% of a household's total annual income, non-senior household) and for Seniors apartments (30% of a household's adjusted income). It does not state one for Special Needs Housing. The requirement to be functionally independent is stated for the seniors programs. Alberta.ca refers to an income thresholds document rather than publishing a single income limit.","aboutList":{"lead":"Special Needs Housing is one of four provincial affordable housing program types, alongside Community Housing, Seniors apartments and Seniors Lodge.","items":["It serves individuals who have special housing needs and may include support services for residents.","Applying takes three steps: use the Find Housing tool to see which options are available to meet your needs, choose a local housing provider offering a program that suits your situation, then contact that provider directly for their application.","Alberta.ca states a rent formula for Community Housing (30% of a household's total annual income, non-senior household) and for Seniors apartments (30% of a household's adjusted income). It does not state one for Special Needs Housing.","The requirement to be functionally independent is stated for the seniors programs.","Alberta.ca refers to an income thresholds document rather than publishing a single income limit." ]},"steps":["Use the Find Housing tool at findhousing.alberta.ca and answer its questions","Look through the options it displays and choose a local housing provider offering a program that suits your situation","Contact that provider directly to get and submit their application","Check the income limit for your own community, because limits are set locally rather than province-wide" ],"documents":["Alberta.ca does not publish a province-wide document list, so ask the local housing provider what their application requires" ],"tips":["There is no single provincial application, so different providers may ask for different things. A housing operator may keep a waitlist when there are no current vacancies. Ask each provider how its list works.","Alberta publishes rent formulas for Community Housing and Seniors apartments. For Community Housing, rent is 30% of a household's total annual income (non-senior household). For Seniors apartments, it is 30% of a household's adjusted income. No formula is stated for Special Needs Housing, so ask the provider how rent is worked out.","Special Needs Housing may include support services for residents. Ask what support comes with the unit. Do not assume it is housing only." ],"time":"Alberta.ca does not publish a wait time. Each housing operator may keep a waitlist when there are no current vacancies."}},{"id":"calgary-fair-entry","name":"Calgary Fair Entry — Transit & Recreation","level":"Calgary","category":"Getting around & recreation","amount":"Transit pass $6.30–$63/month by income band + lower-cost recreation","summary":"One application gets you a low-income monthly transit pass and lower-cost City of Calgary pools, fitness and recreation programs.","requires":["calgary","lowIncome" ],"note":"Apply once through Fair Entry. The transit pass has three 2026 income bands: $6.30, $44.10 or $63.00 per month.","applyText":"Apply through Calgary Fair Entry","applyUrl":"https://www.calgary.ca/social-services/low-income/fair-entry-subsidy.html","source":"https://www.calgary.ca/social-services/low-income/fair-entry-subsidy.html","detail":{"about":"A single City of Calgary application ('Fair Entry') that qualifies you for several low-income discounts at once — the sliding-scale monthly transit pass and lower-cost recreation admission and programs. Calgary does not publish a fixed percentage for recreation fee assistance.","steps":["Gather proof of income for your household.","Apply online through Fair Entry (or in person).","Once approved, buy the low-income transit pass and use your Fee Assistance card for recreation." ],"documents":["Proof of income (e.g. tax assessment or benefit statements)","Calgary address" ],"tips":["One approval covers transit and recreation. You do not apply separately.","The transit pass price changes with income. There are three 2026 bands: $6.30, $44.10 or $63.00 per month." ],"time":"Usually processed within a couple of weeks.","phone":"City of Calgary 311"}},{"id":"edmonton-fare-assistance","name":"Edmonton Ride Transit & Leisure Access","level":"Edmonton","category":"Getting around & recreation","amount":"Reduced-cost monthly Arc transit card ($35 or $50 a month, depending on household income) + Leisure Access Pass","summary":"A subsidized monthly Arc transit card plus reduced-cost access to City of Edmonton recreation facilities.","requires":["edmonton","lowIncomeOrDisabilityIncome" ],"note":"You may be eligible if your household income is at or under the City's limits. The limits depend on household size. You may also be eligible if you get AISH or CPP Disability Benefits, among other programs the City lists. Use the City's eligibility questions to check.","applyText":"Open the official page on edmonton.ca","applyUrl":"https://www.edmonton.ca/ets/fare-assistance","source":"https://www.edmonton.ca/ets/fare-assistance","detail":{"about":"City of Edmonton programs that give lower-income residents a discounted monthly transit pass (the Ride Transit Program) and reduced-cost recreation access (the Leisure Access Program).","steps":["Complete the Leisure Access / Ride Transit application.","Include proof of income or proof you receive AISH / CPP-D.","Once approved, buy your reduced-cost monthly Arc card (the City lists $35 or $50 a month depending on household income) and use your Leisure Access pass." ],"documents":["Proof of income or AISH / CPP-D statement","Edmonton address" ],"tips":["Use the City's eligibility questions to check the Ride Transit Program and/or the Leisure Access Pass.","If you get AISH or CPP Disability Benefits, the City's eligibility check says you may be eligible without meeting the income limit." ],"time":"Approximately 8 to 12 weeks for approval. If you ask for your Arc card by mail, allow up to 10 more business days; you can pick it up in person instead.","phone":"City of Edmonton 311"}},{"id":"reddeer-fee-assistance","name":"Red Deer Transit & Recreation Fee Assistance","level":"Red Deer","category":"Getting around & recreation","amount":"$34/month transit pass + up to $200/year per eligible person for recreation programs (pending available funding)","summary":"A reduced monthly transit pass plus help with City recreation fees. If you are on AISH, you may automatically qualify when you show the City your documents.","requires":["reddeer","lowIncomeOrDisabilityIncome" ],"note":"If you're on AISH or Income Support, you may automatically qualify when you provide the listed document. You may not need to send a Notice of Assessment. The transit pass is a permanent program (not a pilot). Both programs need renewing each year.","applyText":"Open the official page on reddeer.ca","applyUrl":"https://www.reddeer.ca/city-services/transit/fares-and-passes/transit-fare-assistance-pass/","source":"https://www.reddeer.ca/recreation-and-culture/recreation/facility-admission-fees--pass-prices/fee-assistance-program/","detail":{"about":"Two City of Red Deer programs. The Transit Fare Assistance Pass drops a monthly pass to $34 no matter which type you'd normally buy (regular passes run $62–$75). The Recreation Fee Assistance Program adds a Recreation Pass Card for drop-in use plus, pending available funding, up to $200 a year per eligible person toward Safe & Healthy Communities program registrations.","aboutList":{"lead":"Two City of Red Deer programs.","items":["The Transit Fare Assistance Pass drops a monthly pass to $34 no matter which type you'd normally buy (regular passes run $62–$75).","The Recreation Fee Assistance Program adds a Recreation Pass Card for drop-in use.","Plus, pending available funding, up to $200 a year per eligible person toward Safe & Healthy Communities program registrations." ]},"steps":["Apply online for Recreation Fee Assistance, or for the Transit Fare Assistance Pass — being approved for recreation also qualifies you for transit.","If you're on AISH or Income Support, provide that document (Guaranteed Income Supplement qualifies for the transit pass only) — the City says you may automatically qualify.","Otherwise attach your CRA Notice of Assessment so they can check you against the low-income line.","Allow up to 10 business days (recreation applications may take longer due to high volume), then buy the $34 pass.","Re-apply every year — approval expires." ],"documents":["Proof you're on AISH / Income Support (or GIS, for the transit pass only) — or a CRA Notice of Assessment","Government-issued ID, and proof of residence if your ID does not show your current Red Deer address" ],"tips":["One application can cover both. Being approved for Recreation Fee Assistance is itself a way to qualify for the transit pass.","Recreation funding is 'pending available funding'. Apply early in the year, not late.","Sorensen Station staff will help you apply in person if the online form is hard to use." ],"time":"Transit pass: up to 10 business days. Recreation: the City says processing may take over 10 business days due to high volume.","phone":"Fee Assistance Program: 403-309-8411 (or feeassistance@reddeer.ca)"}},{"id":"lethbridge-fee-assistance","name":"Lethbridge Fee Assistance Program","level":"Lethbridge","category":"Getting around & recreation","amount":"3 months of bus passes for the price of 1 (you pay for one month, two are free) + up to $150 per person per season toward one recreation or culture program, while funds are available","summary":"One City program covers transit, Access-A-Ride paratransit, and recreation fees. Each has a separate application form. AISH counts as proof of income.","requires":["lethbridge","lowIncomeOrDisabilityIncome" ],"note":"This is the only one of these city programs that also helps pay for paratransit (Access-A-Ride). This is worth knowing if you can't use a regular bus.","applyText":"Open the official page on lethbridge.ca","applyUrl":"https://www.lethbridge.ca/community-services-supports/community-social-development-csd/fee-assistance-program/","source":"https://www.lethbridge.ca/community-services-supports/community-social-development-csd/fee-assistance-program/","detail":{"about":"A single City of Lethbridge program covering three things: bus passes (you pay for one month and get the next two free), Access-A-Ride paratransit at one-third of the usual cost, and recreation or culture programs.","steps":["Apply online using the Fee Assistance application form for what you need (recreation and culture, bus pass, or Access-A-Ride), or call 311 for help.","Send your AISH statement as proof of income — it's on their accepted list, so you don't need a Notice of Assessment.","Choose what you need: bus pass, Access-A-Ride, recreation, or more than one — each has its own form.","Buy your one paid month of bus pass and the next two come free." ],"documents":["AISH statement — or a CRA Notice of Assessment, Alberta Works letter, housing authority letter, or a letter from a Registered Social Worker","Proof of a Lethbridge address" ],"tips":["A letter from a Registered Social Worker is accepted on its own. This helps if your paperwork is a mess or your income is hard to document.","Recreation funding has a limit per season. Claim it in a season when a program costs more.","CommunityLINKS at the main library will sit with you and do the application." ],"time":"Apply any time; funding runs while it lasts.","phone":"311, or 403-320-3111 from outside Lethbridge"}},{"id":"medicinehat-fair-entry","name":"Medicine Hat Fair Entry","level":"Medicine Hat","category":"Getting around & recreation","amount":"up to 75% off transit (up to $630/yr per person) + up to $200/yr per person for City recreation, and a separate up to $200/yr per person for Esplanade education programs","summary":"One application, valid up to two years, for cheaper transit passes plus recreation and Esplanade education programs.","requires":["medicinehat","lowIncomeOrDisabilityIncome" ],"note":"Approval lasts up to two years, so you renew less often than with most programs here. A copy of your current AISH Health Benefits Card is accepted as proof.","applyText":"Open the application form on medicinehat.ca","applyUrl":"https://forms.medicinehat.ca/Community-Development/Fair-Entry-Application","source":"https://www.medicinehat.ca/community-support-culture-safety/community-support/fair-entry/","detail":{"about":"The City of Medicine Hat's single low-income access program. It can take up to 75% off age-appropriate monthly transit passes (to an annual maximum of $630 subsidy per person). It gives each approved person up to $200 a year for regular-priced City recreation programs and admissions at City-run pools and leisure centres, plus a separate up to $200 a year for Esplanade education programs provided directly by Esplanade staff, at 75% off.","aboutList":{"lead":"The City of Medicine Hat's single low-income access program has separate subsidies for each service area.","items":["Transit: up to 75% off age-appropriate monthly passes, to an annual maximum of $630 subsidy per person.","City recreation: up to $200 a year per approved person, at 75% off.","Eligible recreation: regular-priced City programs and admissions at City-run pools and leisure centres.","Esplanade: a separate up to $200 a year per approved person, at 75% off.","Eligible Esplanade programs: education provided directly by Esplanade staff." ]},"steps":["Fill in the Fair Entry application online, or call 403-502-8001.","Attach a copy of your current AISH Health Benefits Card — it's accepted as proof of income. Provide a document for each household member aged 18 or older.","Add proof of a Medicine Hat address.","Your application should be processed within two weeks, but approval depends on the information you provide, and missing information may delay it." ],"documents":["A copy of your current AISH Health Benefits Card — or another accepted proof of income from the City's list (for example a CRA Notice of Assessment or an Alberta Works document). Provide a document for each household member aged 18 or older.","A letter from a social worker or support staff is accepted only when no other documents are available. It must be dated within the last 30 days and come from someone you have a current relationship with.","The letter must state the length of the relationship, that the writer is aware of the Low Income Eligibility, and that your household meets the eligibility requirements.","Proof of a Medicine Hat address" ],"tips":["List every family member on the one application. Each approved person gets their own $200 recreation subsidy.","Approval is good for up to two years. Note the expiry date in your calendar, so you know when to re-apply." ],"time":"Processed within two weeks; missing information may delay approval.","phone":"Fair Entry: 403-502-8001"}},{"id":"grandeprairie-aish-pass","name":"Grande Prairie AISH Transit Pass & Recreation Access","level":"Grande Prairie","category":"Getting around & recreation","amount":"$10.25/month transit pass + 75% off recreation","summary":"If you're on AISH, a monthly Grande Prairie transit pass costs $10.25 instead of $74.25.","requires":["grandeprairie","municipalProgramEligibility" ],"note":"Important: AISH and ADAP recipients are not part of the general Transit Access Program. You get your own, cheaper pass instead ($10.25 vs $37.13). Ask for the AISH pass by name at City Hall.","applyText":"Open the official page on cityofgp.com","applyUrl":"https://cityofgp.com/roads-transportation/public-transit/fares-superpass","source":"https://cityofgp.com/roads-transportation/public-transit/transit-access-program","detail":{"about":"Grande Prairie prices a monthly transit SUPERPASS at $10.25 for AISH recipients, against $74.25 at the regular adult rate. It's separate from the city's general low-income Transit Access Program, which AISH recipients are explicitly excluded from — because this is the better deal. The Recreation Access Program is a separate application giving 75% off memberships, punch passes and registered programs.","aboutList":{"lead":"Grande Prairie prices a monthly transit SUPERPASS at $10.25 for AISH recipients, against $74.25 at the regular adult rate.","items":["It's separate from the city's general low-income Transit Access Program, which AISH recipients are explicitly excluded from — because this is the better deal.","The Recreation Access Program is a separate application giving 75% off memberships, punch passes and registered programs." ]},"steps":["For the transit pass: go to City Hall (10205 98 Street) and ask for the AISH monthly pass — bring your AISH documentation.","For recreation: apply separately to the Recreation Access Program, online or in person.","In-person applications are approved on the spot — about 15 minutes. Online takes about 2 days." ],"documents":["Proof you receive AISH (or ADAP)","Proof of a Grande Prairie address","For recreation: household income and any dependent children's details" ],"tips":["Don't let anyone put you in the Transit Access Program instead. It is a 50% discount ($37.13), and the AISH pass is $10.25. Say 'AISH pass' clearly.","The Recreation Access Program uses a higher income line than most (the low-income cut-off plus 30%). Apply even if you've been refused elsewhere." ],"time":"Same day in person; about 2 days online.","phone":"City of Grande Prairie: 780-538-0300 or 311"}},{"id":"stalbert-subsidy","name":"St. Albert Transit & Recreation Subsidy","level":"St. Albert","category":"Getting around & recreation","amount":"Free local fares within St. Albert + free annual recreation membership for AISH and ADAP recipients","summary":"St. Albert's subsidy gives eligible residents free local fares within St. Albert and free local Handibus tickets for approved riders. AISH and ADAP recipients are eligible for a free annual membership at City-run recreation facilities.","requires":["stalbert","municipalProgramEligibility" ],"note":"AISH and ADAP recipients are eligible for a free annual recreation membership. The City's page also says your total annual household income (before taxes) must be within the low-income limits set by Statistics Canada. It does not say whether that rule applies to AISH or ADAP recipients, so confirm with the City.","applyText":"Open the official page on stalbert.ca","applyUrl":"https://stalbert.ca/city/fcss/programs-services/subsidy/","source":"https://stalbert.ca/city/fcss/programs-services/subsidy/","detail":{"about":"St. Albert's Family and Community Support Services runs one subsidy covering transit and recreation. For eligible residents: free local fares within St. Albert; free local tickets for approved Handibus riders for travel within St. Albert; 65% off monthly adult commuter fares for travel between St. Albert and Edmonton; AISH and ADAP recipients are eligible for a free annual membership at City-run recreation facilities, including Servus Credit Union Place, Fountain Park Recreation Centre and Grosvenor Outdoor Pool.","aboutList":{"lead":"St. Albert's Family and Community Support Services runs one subsidy covering transit and recreation. For eligible residents:","items":["Free local fares within St. Albert","Free local tickets for approved Handibus riders for travel within St. Albert","65% off monthly adult commuter fares for travel between St. Albert and Edmonton","AISH and ADAP recipients are eligible for a free annual membership at City-run recreation facilities, including Servus Credit Union Place, Fountain Park Recreation Centre and Grosvenor Outdoor Pool" ]},"steps":["Fill in the subsidy application on the City's subsidy page.","Say that you receive AISH or ADAP — AISH and ADAP recipients are eligible for the free annual recreation membership.","If you use the Handibus, ask about approved-rider status at the same time.","Call 780-459-1756 if you get stuck." ],"documents":["Proof you receive AISH or ADAP","Proof of a St. Albert address" ],"tips":["You can't claim this if another source already funds the same thing. If a program already pays your bus fare, sort that out first.","The commuter fare between St. Albert and Edmonton is separate from free local fares. Ask about both if you travel in." ],"time":"Allow a couple of weeks.","phone":"St. Albert FCSS: 780-459-1756"}},{"id":"strathcona-subsidy","name":"Strathcona County Everybody Rides & Everybody Gets to Play","level":"Sherwood Park","category":"Getting around & recreation","amount":"Reduced transit fare cap + free annual Active Pass+","summary":"Reduced transit fares on your Arc card and a no-cost annual Active Pass+ for County recreation facilities, for residents on a limited income.","requires":["strathcona","lowIncomeOrDisabilityIncome" ],"note":"These programs are based on income, not disability. The income line is roughly $33,675/year for one person. If your household income is under that, it's worth applying.","applyText":"Open the official page on strathcona.ca","applyUrl":"https://www.strathcona.ca/community-families/affordable-services/subsidized-fares/","source":"https://www.strathcona.ca/community-families/affordable-services/","detail":{"about":"Two Strathcona County programs. Everybody Rides puts a reduced monthly fare cap on your Arc card profile for local and commuter travel. Everybody Gets to Play gives a free annual Active Pass+ for County recreation facilities plus reduced fees on programs.","steps":["Call Family and Community Services at 780-464-4044, or go to 401 Festival Lane (Community Centre, 2nd floor).","Bring ID, proof you live in the County, and your Notice of Assessment (see the documents list for the exceptions).","Ask about both programs in the one visit — they're separate but handled by the same team." ],"documents":["Photo ID","Proof of a Strathcona County address","Notice of Assessment (NOA) from the Canada Revenue Agency — a 2025 NOA is required starting June 1, 2026, and a 2024 NOA is no longer accepted","If your NOA no longer reflects your current finances, bring 3 months of bank statements as well","New refugee or permanent resident in the first year with no NOA: 3 months of bank statements from a Canadian bank" ],"tips":["The County adjusts its income limits every year. A refusal from years ago is not a reason to skip re-applying.","Everybody Rides works by changing the fare cap on your Arc card. You keep using the same card." ],"time":"Ask when you apply — it isn't published.","phone":"Family and Community Services: 780-464-4044"}},{"id":"airdrie-fair-access","name":"Airdrie Fair Access","level":"Airdrie","category":"Getting around & recreation","amount":"25–75% off transit passes + Genesis Place recreation","summary":"One income-tested application covering Airdrie transit passes and Genesis Place recreation, at 25%, 50% or 75% off depending on income.","requires":["airdrie","lowIncomeOrDisabilityIncome" ],"note":"Airdrie checks your household income against its limits. The page does not say that being on AISH qualifies you automatically. An AISH or ADAP form showing your eligibility period is one of the accepted proof-of-income documents. AISH/ADAP recipients get a two-year term instead of one year.","applyText":"Open the official page on airdrie.ca","applyUrl":"https://www.airdrie.ca/index.cfm?serviceID=2414","source":"https://www.airdrie.ca/index.cfm?serviceID=2157","detail":{"about":"The City of Airdrie's single low-income subsidy (formerly the Airdrie Participant Support Program). One application covers transit passes and Genesis Place recreation admissions, passes and registered programs. The discount is tiered: 75%, 50% or 25% depending where your household income falls against the low-income cut-off before tax.","aboutList":{"lead":"The City of Airdrie's single low-income subsidy (formerly the Airdrie Participant Support Program).","items":["One application covers transit passes and Genesis Place recreation admissions, passes and registered programs.","The discount is tiered: 75%, 50% or 25% depending where your household income falls against the low-income cut-off before tax." ]},"steps":["Apply online through the Airdrie Fair Access form — it's a one-step application.","Show household income; the tier you land in (75 / 50 / 25%) is worked out from it.","Call Community Links on 403-945-3900 if you want help with the form." ],"documents":["Proof of household income","Proof of an Airdrie address" ],"tips":["Income up to 25% above the low-income cut-off still gets you the 25% tier. Don't assume you earn too much.","If you use Access Airdrie (paratransit), ask about it when you apply. The eligible services list names ACCESS Airdrie, the paratransit service." ],"time":"Ask when you apply.","phone":"City of Airdrie: 403-948-8800 · Community Links: 403-945-3900"}},{"id":"woodbuffalo-lift","name":"Wood Buffalo LIFT (Low-Income Fare Transit)","level":"Fort McMurray","category":"Getting around & recreation","amount":"$10/month transit pass + 75% off SMART Bus + 60% off recreation","summary":"A $10 monthly transit pass, 75% off specialized SMART Bus passes, and 60% off regional recreation memberships through a community partner.","requires":["woodbuffalo","lowIncomeOrDisabilityIncome" ],"note":"This is one of only two municipal programs here that discount specialized (door-to-door) transit. The other is Lethbridge's Access-A-Ride. Your AISH statement is accepted as proof of income.","applyText":"Open the application form on rmwb.ca","applyUrl":"https://forms.rmwb.ca/Community-Services/LIFT-Program-Application","source":"https://www.rmwb.ca/LIFT","detail":{"about":"The Regional Municipality of Wood Buffalo's Low-Income Fare Transit program: a monthly conventional transit pass for $10, and 75% off 10- and 25-ride passes for the SMART Bus (the specialized service for seniors and people with mobility needs). Everyone in the household is covered by the one application. The Wood Buffalo Recreation Support Program is a separate program that gives 60% off memberships at Syncrude Sport and Wellness Centre, Regional Recreation Corporation facilities and Vista Ridge. The LIFT page says only one application is required to assess eligibility for these community partner discounts.","aboutList":{"lead":"The Regional Municipality of Wood Buffalo's Low-Income Fare Transit program: a monthly conventional transit pass for $10, and 75% off 10- and 25-ride passes for the SMART Bus (the specialized service for seniors and people with mobility needs).","items":["Everyone in the household is covered by the one application.","The Wood Buffalo Recreation Support Program is a separate program that gives 60% off memberships at:","Syncrude Sport and Wellness Centre, Regional Recreation Corporation facilities and Vista Ridge.","The LIFT page says only one application is required to assess eligibility for these community partner discounts." ]},"steps":["Apply online for LIFT, or email community.services@rmwb.ca, or apply in person.","Send your AISH statement as proof of income — it's accepted.","You will be notified within 7–10 business days if you submit a complete application.","For SMART Bus, buy the discounted 10- or 25-ride passes directly from the operator once you're approved.","Ask the City or the Recreation Support Program how to claim the 60% recreation discount once you are approved; the LIFT page says one application assesses eligibility." ],"documents":["AISH statement (or other proof of household income)","Proof of a Wood Buffalo address" ],"tips":["The income line here is high: about $35,500 for one person, well above AISH.","One application covers your partner and dependent children too, not just you.","Call Pulse on 780-743-7000 if anything about the form is unclear.","You must be 18 or older to apply (people under 18 who live independently may be considered)" ],"time":"Notification within 7–10 business days of a complete application.","phone":"Pulse: 780-743-7000"}},{"id":"sprucegrove-low-income-transit","name":"Spruce Grove Low Income Transit Pass","level":"Spruce Grove area","category":"Getting around","amount":"$25/month local or $50/month commuter transit pass","summary":"A reduced local or commuter transit pass for qualifying Spruce Grove-area residents.","requires":["sprucegrovearea","lowIncome" ],"note":"The City accepts applications year-round. The program also serves eligible Stony Plain and Parkland County residents.","applyText":"Open the official page on sprucegrove.org","applyUrl":"https://www.sprucegrove.org/services/spruce-grove-transit/transit-fares/","source":"https://www.sprucegrove.org/services/spruce-grove-transit/transit-fares/","detail":{"about":"A City of Spruce Grove subsidized transit pass. Qualifying adults can buy a local pass for $25 a month or a commuter pass for $50 a month.","steps":["Read the City’s current eligibility rules and application instructions.","Apply with proof of address and household income.","Choose the local or commuter pass that matches your trips." ],"documents":["Proof of address","Proof of household income" ],"tips":["The City says applications are accepted year-round.","Stony Plain and Parkland County residents should confirm the local address rules on the City page before applying." ],"time":"Applications are accepted year-round."}},{"id":"leduc-subsidies","name":"Leduc Transit & Recreation Subsidies","level":"Leduc","category":"Getting around & recreation","amount":"Half-price monthly bus pass of your choice (local, commuter or LATS)","summary":"Financial-navigation support that can provide a half-price monthly bus pass. You choose a local, commuter or LATS pass. The Recreation Assistance Program is now closed. It will reopen for new applications in January 2027.","requires":["leduc","lowIncome" ],"note":"Leduc lists half-price monthly bus passes. You can choose a local, commuter or LATS monthly pass. All Recreation Assistance Program funding for 2026 has been fully allocated. The program is now closed and will reopen for new applications in January 2027.","applyText":"Contact Leduc FCSS about subsidies","applyUrl":"https://www.leduc.ca/community/family-community-support-services/housing-financial-support","source":"https://www.leduc.ca/community/family-community-support-services/housing-financial-support","detail":{"about":"Leduc Family and Community Support Services can help qualifying residents access a half-price monthly bus pass as part of its housing and financial-navigation support. The Recreation Assistance Program is now closed and will reopen for new applications in January 2027.","steps":["Contact Leduc FCSS for a financial-navigation appointment.","Ask about the transit subsidy when discussing your situation. Ask when the Recreation Assistance Program reopens.","Follow their directions for the documents needed to assess eligibility." ],"documents":["Proof of Leduc residence","Financial information requested by FCSS" ],"tips":["You choose a local, commuter or LATS monthly pass. Ask specifically about LATS if you use specialized transit.","The City’s page describes an assessment. Do not assume you are eligible until FCSS confirms it." ],"time":"Ask FCSS when you contact them."}},{"id":"cochrane-connect-card","name":"Cochrane Connect Card","level":"Cochrane","category":"Getting around & recreation","amount":"25% off local transit + 50% off SLS Centre monthly passes","summary":"A Town card for residents facing financial or situational barriers, with local transit and recreation discounts.","requires":["cochrane","lowIncome" ],"note":"Cochrane assesses financial and situational need. Book an appointment and bring the requested income and address documents for all adults in the household.","applyText":"Open the official page on cochrane.ca","applyUrl":"https://www.cochrane.ca/node/241/financial-resources/cochrane-connect-card","source":"https://www.cochrane.ca/node/241/financial-resources/cochrane-connect-card","detail":{"about":"The Cochrane Connect Card gives qualifying residents 25% off COLT monthly and 10-ticket transit passes, and 50% off SLS Centre 30-day and monthly passes.","steps":["Book the appointment described on the Town’s Connect Card page.","Bring proof of income and your Cochrane address for all adults in the household.","Ask which current transit and SLS Centre discounts the card gives you." ],"documents":["Proof of income (for all adults in the household)","Proof of Cochrane address (for all adults in the household)" ],"tips":["This is not only an income test; the Town also describes situational need.","Confirm the current eligible passes at your appointment before purchasing." ],"time":"Ask when booking the appointment."}},{"id":"okotoks-fee-assistance","name":"Okotoks Recreation Fee Assistance","level":"Okotoks","category":"Recreation","amount":"80% off most Town programs, passes and admission","summary":"A recreation-fee subsidy for qualifying low-income Okotoks and Foothills County residents.","requires":["ab","okotoksArea","okotoksResidency","lowIncome" ],"note":"The Town describes 80% support for most Town programs, passes and admission. Check current exclusions and camp limits before registering.","applyText":"Open the official page on okotoks.ca","applyUrl":"https://www.okotoks.ca/your-community/social-well-being/family-community-resources/okotoks-family-resource-centre-7","source":"https://www.okotoks.ca/your-community/social-well-being/family-community-resources/okotoks-family-resource-centre-7","detail":{"about":"The Town’s Recreation Fee Assistance Program helps qualifying residents afford most Town recreation programs, passes and admission at an 80% discount.","steps":["Read the Town’s current program information and eligibility rules.","Apply with the income and residence documents requested.","Check the program period and any limits before registering for an activity." ],"documents":["Proof of income","Proof of Okotoks residence" ],"tips":["The Town also serves eligible Foothills County residents. If that is you, confirm the current boundary rule.","Ask about exclusions before choosing a camp or program." ],"time":"Ask when you apply."}},{"id":"canmore-affordable-services","name":"Canmore Affordable Services Program","level":"Canmore","category":"Getting around & recreation","amount":"Discounts on Regional ROAM Transit, recreation and community services","summary":"A Town program that gives qualifying residents lower-cost services, including Regional ROAM Transit and recreation.","requires":["canmore","lowIncome" ],"note":"The Town lists discounts across Regional ROAM Transit, recreation and community services. Transit discount tiers differ, so confirm the current rate for your household.","applyText":"Open the official page on canmore.ca","applyUrl":"https://www.canmore.ca/your-community/community-supports-and-services/affordable-services-program","source":"https://www.canmore.ca/your-community/community-supports-and-services/affordable-services-program","detail":{"about":"Canmore’s Affordable Services Program provides qualifying residents with discounts on Town and community services, including Regional ROAM Transit and recreation.","steps":["Review the Town’s current eligibility and application instructions.","Apply with the income and residency documents requested.","Ask which discounts apply to the services you use." ],"documents":["Proof of income","Proof of Canmore residence" ],"tips":["Transit discounts are tiered. The Town page has the current rate.","Apply before assuming a discount is available for a specific community service." ],"time":"Ask when you apply."}},{"id":"lloydminster-recreation-access","name":"Lloydminster Recreation Access Program","level":"Lloydminster","category":"Recreation","amount":"$2 adult drop-in admission at City recreation facilities","summary":"Income-based recreation access for eligible Lloydminster residents. First Nations, Metis, and/or Inuit applicants do not need to meet the residency requirement. They must still meet the income eligibility.","requires":["lloydminster","lowIncome" ],"note":"The City lists income-based access to City recreation facilities, including $2 adult drop-in admission. Confirm all current discounts when applying.","applyText":"Open the official page on lloydminster.ca","applyUrl":"https://www.lloydminster.ca/recreation-culture-community/social-programs-and-services/recreation-access-program/","source":"https://www.lloydminster.ca/recreation-culture-community/social-programs-and-services/recreation-access-program/","detail":{"about":"Lloydminster’s Recreation Access Program gives qualifying low-income residents reduced-cost access to City recreation facilities.","steps":["Review the City’s current income criteria and application instructions.","Apply with the documents the City requests.","Ask the recreation desk which current facility admissions and passes are covered." ],"documents":["Proof of household income","Proof of Lloydminster residence (not required of First Nations, Metis, and/or Inuit applicants, who provide a copy of a Certificate of Indian Status card and/or a Certificate of Treaty Status card, as the page lists)" ],"tips":["Use the official City page to confirm current rates before you plan around a discount.","Ask whether your household members can be included in the application." ],"time":"Ask when you apply."}},{"id":"fortsask-access","name":"Fort Saskatchewan Access for Everyone","level":"Fort Saskatchewan","category":"Getting around & recreation","amount":"Free multi-facility membership + reduced local or commuter transit fares","summary":"Recreation and transit support for eligible Fort Saskatchewan residents with limited income or approved income support.","requires":["fortsask","fortsaskIncomeRoute" ],"note":"The City lists a fully discounted annual multi-facility membership and an Everyone Rides transit subsidy. It also accepts several approved income-support programs. Confirm your route when applying.","applyText":"Open the official page on fortsask.ca","applyUrl":"https://www.fortsask.ca/recreation-parks/program-registrations-drop-in-classes/access-for-everyone-program/","source":"https://www.fortsask.ca/recreation-parks/program-registrations-drop-in-classes/access-for-everyone-program/","detail":{"about":"Fort Saskatchewan’s Access for Everyone Program combines recreation support with the Everyone Rides transit subsidy for eligible residents.","steps":["Review the City’s current eligibility routes and application instructions.","Apply with proof of limited income or the approved income-support document that applies to you.","Ask about both the recreation membership and Everyone Rides transit subsidy." ],"documents":["Proof of Fort Saskatchewan residence","Proof of income or approved income support" ],"tips":["The City lists AISH, CPP Disability, FSCD and Income Support as approved programs. Check the current page for full details.","Ask whether your local or commuter transit trips qualify before buying a pass." ],"time":"Ask when you apply."}},{"id":"banff-access-program","name":"Banff Access Program","level":"Banff","category":"Recreation","amount":"Free Banff Access Card for reduced rates on recreation and transit passes","summary":"A free card that lowers the cost of recreation programs, transit passes and other participating services for Banff residents with lower household income.","note":"The card cannot be combined with other subsidies or discounts, and it is not transferable. It is cancelled if you no longer qualify, for example if you move out of Banff.","requires":["ab","banff","banffAccessProgramRoute" ],"eligibility":{"mode":"all","items":["You live at a street address in the Town of Banff","Your gross household income is at or below the limit for your household size","You can show a need to reside in Banff, such as an employment contract","You are a Canadian citizen, permanent resident or closed work permit holder","You have lived in Banff for 3 full months, or 6 with an eligible open work permit" ],"note":"Limits are tiered by household size; the one-person amounts are in the tips."},"applyText":"Apply for the Banff Access Card","applyUrl":"https://banff.ca/963/Banff-Access-Program","source":"https://banff.ca/963/Banff-Access-Program","detail":{"aboutList":{"lead":"The Banff Access Card gives reduced rates on recreation, transit passes and other participating services.","items":["Adults 18 and older, and their children under 18 at the same address, can apply together.","Staff living at the Rimrock Hotel or on Juniper Way apply through the ID9 Access Program instead.","Open work permits that allow a 6-month wait include Working Holiday and Post-Graduate permits.","Partner open work permits and International Student work permits also allow a 6-month wait.","Post office boxes and General Delivery are not accepted as proof of address." ]},"steps":["Check your household income against the limit for your household size.","Gather your proof of income, address, need to reside and residency status.","Email your documents to Community.Services@banff.ca with the subject line Banff Access Application.","Wait for a decision, because sending documents does not guarantee access." ],"documents":["Three current pay stubs from each job, or proof of government benefits such as AISH or EI","Your most recent Notice of Assessment showing line 15000","Proof of your Banff address, such as a utility bill, lease or financial document","An employment contract or a signed employer letter on letterhead","Proof of status, such as a Canadian passport, PR card or closed work permit","If reapplying, a Notice of Assessment from your previous tax year" ],"tips":["For one person, Tier 1 is $40,643.20 and Tier 2 is $48,771.84.","If your hours were cut or you were laid off, ask Community Services about your situation.","You can find your Notice of Assessment in your Canada Revenue Agency account.","Free help with taxes may be available for residents with low income and simple returns." ],"phone":"403-762-1251"}},{"id":"blackfalds-recreation-fee-assistance","name":"Recreation Fee Assistance Program (PASS)","level":"Blackfalds","category":"Recreation","amount":"Subsidized fees for Town programs, memberships and admissions","summary":"Helps Blackfalds residents with low household income pay fees for Town programs, memberships and admissions. The Town subsidizes fees when possible.","note":"One application also assesses you for Tools for School, Winter Wear and the Christmas Bureau. When your approval period ends, you must re-apply with all documents.","requires":["ab","blackfalds","blackfaldsRecreationFeeAssistanceRoute" ],"eligibility":{"mode":"all","items":["You live in Blackfalds","Your total household income is below the Statistics Canada Low Income Cut-Off","You send proof of income with your application" ],"note":"Proof can be a Notice of Assessment, an AISH or Alberta Works health card, or a social worker letter."},"applyText":"Get the application form","applyUrl":"https://irec.wolfcreek.ab.ca/download/108425","source":"https://irec.wolfcreek.ab.ca/download/108425","detail":{"aboutList":{"lead":"The Town of Blackfalds subsidizes fees for people who cannot pay for municipal recreation.","items":["Covers municipally operated programs, memberships and admissions.","The subsidy is given when possible, so funding may limit it.","FCSS assesses your income and sends you a notice telling you what to do next.","Household means people in one dwelling who are related by blood, marriage, common-law or adoption.","The limits are the Statistics Canada Low Income Cut-Offs, which are updated each year." ]},"steps":["Fill in the Subsidized Program Application and tick the programs you want.","Add a copy of one income document. Do not mail originals.","Drop it off at the FCSS office, or send it by mail or fax.","Expect a notice within two to four weeks.","Show your approval notice, proof of identity and proof of Blackfalds residency to use the subsidy." ],"documents":["A current Notice of Assessment for each family member 18 and over, not a tax return summary","Or a current AISH or Alberta Works health benefits card that has not expired","Or a Registered Social Worker letter dated within 30 days, only if no other document exists","Or a Resettlement Assistance Program Start-Up and Monthly Allowance form","Or, for independent youth, a school principal or guidance counsellor letter" ],"tips":["If you are declined and your finances change, you can reapply with no waiting period.","Processing can take up to four weeks, so allow time if you apply by mail.","Call the FCSS Manager if you have trouble with the form." ],"time":"Notice in two to four weeks","phone":"403-885-6247"}},{"id":"chestermere-community-access-program","name":"Community Access Program (CAP)","level":"Chestermere","category":"Recreation","amount":"CAP card for subsidies on memberships, classes and transit passes","summary":"A card for low-income Chestermere residents. It gives access to community memberships, classes, transit passes and other offers from local businesses.","note":"Each card expires on December 31 and must be renewed by Community Wellness Services staff. You can ask for the monthly transit subsidy only, or the full program.","requires":["ab","chestermere","chestermereCommunityAccessProgramRoute" ],"eligibility":{"mode":"all","items":["You live in Chestermere","Your household income is low, based on the Low Income Cut-Offs (LICO)","You can show proof of residence, ID for household members and proof of income" ],"note":"The page lists the proofs of income it accepts but does not give a dollar limit."},"applyText":"Register for CAP","applyUrl":"https://thecityofchestermere.ca/community-services/cap-registration/","source":"https://thecityofchestermere.ca/community-services/cap-registration/","detail":{"aboutList":{"lead":"CAP supports low-income Chestermere residents with tax filing, memberships, classes and transit.","items":["The subsidies listed include a transportation subsidy and Kids Up Front tickets.","Others listed are TELUS Spark Centre passes and the Community Volunteer Income Tax Program.","Local partners listed include the Genesis Centre, Luna PLAY and Harmony Health and Fitness.","The Chestermere Regional Community Association and Calgary Yacht Club also appear on the list.","All information given to staff is kept strictly confidential." ]},"steps":["Open the CAP registration form on the city page.","Choose monthly transit subsidy only, or full Community Access Program membership.","Enter your name, email and phone, then submit the form.","Give Community Wellness staff your proof of residence, ID and income." ],"documents":["Proof of Chestermere residence","ID for household members","Proof of income: a Notice of Assessment, AISH benefits, or Alberta Works Learners or Alberta Health Benefit","Or a letter from a Registered Social Worker, or 3 months of bank statements","Or a statement that your income is lower than the Chestermere Living Wage" ],"tips":["The transit-only option is open to adults and youth.","Renew your card each year, because every card ends on December 31." ]}},{"id":"drayton-valley-recreation-fee-assistance","name":"Recreation Fee Assistance Program (RFAP)","level":"Drayton Valley","category":"Recreation","amount":"75% subsidized cost at the aquatic and fitness centres","summary":"Drayton Valley residents with gross household income below the Low Income Cut-Off get a 75% subsidized cost on Town programs at the Aquatic Centre and the Health and Fitness Centre.","note":"Programs must be a Town program or activity that is 4 or more days or classes long, a camp, or a membership. Fundraising or uniform fees, travel to out-of-town competitions and programs of three days or less are not covered.","requires":["ab","draytonValley","draytonValleyRecreationFeeAssistanceRoute" ],"eligibility":{"mode":"all","items":["You live in the Town of Drayton Valley","Your gross household income is below the Statistics Canada Low Income Cut-Off","You send documents that prove income and residency for all adults in the household" ],"note":"The 2025 gross limits run from $30,526 for 1 person to $80,784 for 7 persons."},"applyText":"Get the application form","applyUrl":"https://www.draytonvalley.ca/recreation-fee-assistance-program/","source":"https://www.draytonvalley.ca/recreation-fee-assistance-program/","detail":{"aboutList":{"lead":"The program lowers the cost of recreation for Drayton Valley residents with low income.","items":["Aquatic Centre passes and swimming lessons are covered, as are children's camps of 4 or more days.","Fitness Centre passes, the indoor track and racquetball or squash passes are covered.","Passes can be yearly, 6-month, 3-month, monthly or a 10-visit punch pass.","A family is up to two adults and their dependent children, and you may apply for up to 7 people." ]},"steps":["Download the application form, or pick one up at a Town recreation or civic location.","Attach your income and residency documents to the form.","Seal it in an envelope and drop it at the Community Services Centre, or mail or email it.","Wait to be contacted. If approved, you get a letter listing the programs you can use." ],"documents":["Proof of residence: a driver's license or utility bill with your legal land address, not a P.O. box","Alberta Health Benefits Card or Alberta Income Support Summary to verify income","Or a Notice of Assessment from the most recent tax year for every adult","Or your two most recent pay stubs or bank statements" ],"tips":["You may need an appointment, depending on staff availability.","To get a copy of your assessment, call the Canada Revenue Agency and ask for it by mail.","Documents are needed for all adults in the household." ],"phone":"780.515.4250"}},{"id":"edson-leisure-assist","name":"Leisure Assist (Fee Assistance Program)","level":"Edson","category":"Recreation","amount":"$150 per person, up to $450 per family each year","summary":"Eligible Edson residents get $150 each, or up to $450 per family, toward Town community programs and Leisure Centre admissions and programs.","note":"Funding is limited and first come, first served. Group and facility rentals are excluded. You must reapply each year and give current documents.","requires":["ab","edson","edsonLeisureAssistRoute" ],"eligibility":{"mode":"all","items":["You live in the Town of Edson or Yellowhead County","You get AISH, Alberta Income Support, Alberta Works or the Guaranteed Income Supplement","Or you have refugee status, low income below the LICO, or a reference letter" ],"note":"The Low Income Cut-Off runs from $24,486 for 1 person to $64,797 for 7 or more."},"applyText":"Get the application form","applyUrl":"https://www.edson.ca/public/download/files/350852","source":"https://www.edson.ca/public/download/files/350852","detail":{"aboutList":{"lead":"Leisure Assist adds credit to your account to help with recreation registration fees.","items":["Once approved, your Active Net account is credited with $150 per person.","The credit is capped at $450 per household.","A reference letter can come from a teacher, family school liaison, doctor or social worker.","Each application is valid for a maximum of twelve months." ]},"steps":["Fill in the Leisure Assist application form and list your household members.","Attach proof of identity and the documents for how you qualify.","Drop it off at the Griffiths Park Centre, 5414-6th Ave, or email it to cserv@edson.ca.","Wait for an email about your approval." ],"documents":["Low income: your most recent Canada Revenue Agency Notice of Assessment","AISH or Alberta Income Support: a Health Benefit Card, direct deposit statement or T5007","Guaranteed Income Supplement: a letter or direct deposit statement","Refugee status: a Protected Person Status document, or a Refugee Claimant document","A signed reference letter with the writer's contact information" ],"tips":["If you are declined and your situation changes, you can reapply with no waiting period.","If you do not attend courses you registered for, later applications may be disqualified.","Applications usually take ten business days to process." ],"time":"About ten business days"}},{"id":"rocky-mountain-house-rfap","name":"Recreation Facility Access Program (Rocky Mountain House)","level":"Rocky Mountain House","category":"Recreation","amount":"50% off Town drop-ins, programs and memberships","summary":"Half price on Town of Rocky Mountain House recreation for families and individuals at or under an income limit. Each person gets an Access Card for one year.","note":"Cards cannot be transferred or replaced if lost. The discount cannot be combined with other offers.","requires":["ab","rockyMountainHouse","rockyMountainHouseRfapRoute" ],"eligibility":{"mode":"any","items":["Your total family income is at or under the limit for your family size","You have a referral form from a referral agency that confirms you are eligible" ],"note":"The limit uses line 150 of your latest tax return, from $35,000 for 1 person to $52,500 for 5."},"applyText":"See how to apply","applyUrl":"https://www.rockymtnhouse.com/p/rfap","source":"https://www.rockymtnhouse.com/p/rfap","detail":{"aboutList":{"lead":"Each person in an eligible household gets an Access Card that halves the cost of Town recreation.","items":["Each card allows 24 drop-in admissions at 50% off.","Each card allows 3 program or lesson registrations at 50% off.","Each card allows 1 aquatic or recreation membership at 50% off.","Cards are valid for one year from the day they are issued." ]},"steps":["Check the income limit for your family size on the Town page.","Go to the Clearwater Regional FCSS office with proof of income or a referral form.","Pick up one Access Card for each person in your household.","Use the cards at the Rocky Regional Recreation Centre or the Co-operative Aquatic Centre." ],"documents":["Your most recent income tax return, showing line 150, or a referral form from a referral agency" ],"tips":["Ask Guest Services which programs and lessons can use your card.","Over five people adds $2,500 to the $52,000 base limit for each extra person." ],"time":"Monday to Friday, 8:30 AM to 4:00 PM","phone":"403-847-5270"}},{"id":"strathmore-community-access-card","name":"Community Access Card (Strathmore)","level":"Strathmore","category":"Recreation","amount":"10%, 25%, 50% or 75% off entry fees and memberships","summary":"A discount card for Strathmore residents facing financial barriers. It covers entry and membership fees at three Town recreation facilities. Your income and family size set the discount.","note":"The card does not cover swimming lessons, fitness classes or other programs. Approved cards expire on December 31 and must be renewed each year.","requires":["ab","strathmore","strathmoreCommunityAccessCardRoute" ],"eligibility":{"mode":"all","items":["You live in Strathmore","Your household income and size meet the financial criteria in Town Policy 5104" ],"note":"You must show proof of income and who lives in your household."},"applyText":"See how to apply","applyUrl":"https://www.strathmore.ca/living-here/family-community-support-services/resources-financial-support/community-access-card/","source":"https://www.strathmore.ca/living-here/family-community-support-services/resources-financial-support/community-access-card/","detail":{"aboutList":{"lead":"The card lowers entry and membership fees at Town recreation facilities for residents who qualify.","items":["Discounts are 10, 25, 50 or 75 percent, set by household income and family size.","It works at the Aquatic Centre, the Family Centre Arena and the Motor Products Sports Centre.","The card lists your household members, so entry is private.","Applications are accepted year-round." ]},"steps":["Go to the FCSS office in person, since applications cannot be done any other way.","Bring your documents for every household member.","Submit the application. It is accepted any time of year.","Renew each year, because approvals end on December 31." ],"documents":["Line 15000 from last year's notice of assessment","Alberta Health Care cards or valid ID for each family member applying","Proof of residency","Documents showing AISH, GIS or refugee status, if they apply" ],"tips":["A mid-year approval still ends on December 31.","The Town posts sub-levels and the policy on the same page." ],"phone":"(403) 934-9090"}},{"id":"whitecourt-recreation-fee-assistance","name":"Recreational Fee Assistance Program (Whitecourt)","level":"Whitecourt","category":"Recreation","amount":"Subsidy for 2 programs per session or a 3 month membership","summary":"A subsidy for adults and their dependents under 18 who cannot pay the full fee. It covers programs and memberships at the Allan & Jean Millar Centre. Applications are kept confidential.","note":"The page does not list income limits or the subsidy rate. Families must first apply to KidSport for programs it covers.","requires":["ab","whitecourt","whitecourtRecreationFeeAssistanceRoute" ],"eligibility":{"mode":"all","items":["You live in the Town of Whitecourt or Woodlands County","Your circumstances meet the financial criteria for people unable to pay the full fee","You applied to KidSport first, if you need a program it covers" ],"note":"This is for adults and their dependents under 18."},"applyText":"Visit Guest Services to apply","applyUrl":"https://whitecourt.ca/play/allan-jean-millar-centre/facility-admission-information","source":"https://whitecourt.ca/play/allan-jean-millar-centre/facility-admission-information","detail":{"aboutList":{"lead":"The program helps people who cannot pay full fees use Allan & Jean Millar Centre programs.","items":["Each family member may get help with 2 programs per session.","A 3 month membership may be covered instead.","You can apply again each year.","All applications are held in strict confidence." ]},"steps":["Apply to KidSport first for any programs it covers.","Go to Guest Services at the Allan & Jean Millar Centre to apply.","Call Guest Services at 780-778-3637 for more information." ],"documents":[ ],"tips":["The page does not list the financial criteria, so call Guest Services for more information." ],"phone":"780-778-3637"}},{"id":"high-river-community-access-program","name":"Community Access Program (High River)","level":"High River","category":"Recreation","amount":"50% off programs and recreation admissions","summary":"A CAP card gives lower-income High River residents half price on Town programs and on admissions and passes at the Bob Snodgrass Recreation Complex and Cargill Field House. It also gives a free library card and local discounts.","note":"Apply at the Town of High River's FCSS Resource Centre, and renew your card by June 30 every year.","requires":["ab","highRiver","highRiverCommunityAccessProgramRoute" ],"eligibility":{"mode":"all","items":["You live in High River","Your household income is at or below the limit for your household size" ],"note":"The limits run from $45,000 for 1 person to $72,500 for 7 people."},"applyText":"Pick up an application at FCSS","applyUrl":"https://highriver.ca/community/community-support-services/cap","source":"https://highriver.ca/community/community-support-services/cap","detail":{"aboutList":{"lead":"A card with recreation discounts and local business discounts.","items":["50 per cent off all programs in the Community Program Guide.","50 per cent off admissions and passes at the two recreation facilities.","A free High River library card.","Discounts at some local health, music, thrift and pharmacy businesses." ]},"steps":["Pick up an application at the FCSS Resource Centre, 251 9 Avenue SW","Bring your ID, plus proof of where you live and what you earn","Renew the card by June 30 each year" ],"documents":["Proof you live in High River, such as ID or utility bills","ID for household members, such as health cards or birth certificates","A current Notice of Assessment, or 3 months of bank statements" ],"tips":["Pharmacy discounts are for store-front items only, not prescriptions.","Staff are at the Resource Centre Monday to Friday, 9:00am to 4:00pm." ],"phone":"403-652-8620"}},{"id":"morinville-wrap","name":"Wellness and Recreation Access Program (Morinville)","level":"Morinville","category":"Recreation","amount":"Up to $250 per person","summary":"WRAP helps low-income Morinville people and families pay for leisure centre memberships, fitness classes, children's programs, sports and FCSS camps. Qualified applicants can get up to $250 per person.","note":"You must renew every calendar year. The page says household income must meet the Low-Income Cut-Offs chart. Some applicants must also show AISH, Income Support or Seniors Benefits proof.","requires":["ab","morinville","morinvilleWrapRoute" ],"eligibility":{"mode":"all","items":["You are a resident of the Town of Morinville","Your household income is within the Low-Income Cut-Offs chart for your household size" ],"note":"Some applicants also give proof of AISH, Income Support or Seniors Benefits, or an FCSS social worker's assessment."},"applyText":"Apply for WRAP","applyUrl":"https://www.morinville.ca/things-to-do/morinville-leisure-centre/get-energized/wellness-and-recreation-access-program/","source":"https://www.morinville.ca/things-to-do/morinville-leisure-centre/get-energized/wellness-and-recreation-access-program/","detail":{"aboutList":{"lead":"A subsidy for recreation and FCSS programs.","items":["It covers Morinville Leisure Centre memberships.","It covers Town programs, such as children's sports and adult fitness classes.","It covers FCSS summer, PD day, and fall and spring break camps.","Local agencies with residential support may get Community Care day passes." ]},"steps":["Complete the application form","Contact Morinville FCSS by email or phone","Submit your documents with the application" ],"documents":["Alberta ID or a utility bill showing a Morinville address","A current tax assessment or the last 90 days of bank statements","If on AISH, Income Support or Alberta Seniors Benefits: proof of receipt" ],"tips":["The income limit is $29,380 for 1 person and $77,751 for 7 people.","Community Recreation and FCSS programs are in the Community Program Guide." ],"phone":"780-939-7839"}},{"id":"taber-fee-assistance","name":"Fee Assistance Program (Taber)","level":"Taber","category":"Recreation","amount":"50% off recreation programs and Aquafun Centre fees","summary":"A 50% discount on Community Centre drop-in programs and summer kids day camps. It also gives 50% off Aquafun Centre membership, drop-ins and lessons. Some restrictions apply.","note":"It is for residents of the Town of Taber and the Municipal District of Taber who are below the income thresholds. The card lasts one year, and you can reapply through FCSS.","requires":["ab","taber","taberFeeAssistanceRoute" ],"eligibility":{"mode":"all","items":["You live in the Town of Taber or the Municipal District of Taber","Your income is below the low-income thresholds","FCSS confirms you are eligible" ],"note":"The page sends you to the Fee Assistance Procedure for the thresholds."},"applyText":"Apply through FCSS","applyUrl":"https://www.taber.ca/town-services/recreation/fee-assistance","source":"https://www.taber.ca/town-services/recreation/fee-assistance","detail":{"aboutList":{"lead":"Half price on many Town recreation fees.","items":["50% off Community Centre drop-in programming and summer kids day camps.","50% off Aquafun Centre membership and drop-ins.","50% off lessons and courses, with some restrictions." ]},"steps":["Fill out the application form and apply through FCSS","If eligible, get a referral letter from FCSS","Bring the letter to the Aquafun Centre reception desk","Staff issue each family member a fee assistance card" ],"documents":["The application form","The FCSS referral letter" ],"tips":["Staff try to keep your use of the program confidential.","KidSport and Jumpstart are other programs listed on the page." ],"time":"Card valid one year from referral"}},{"id":"ab-blue-cross-non-group","name":"Alberta Blue Cross Non-Group Coverage","level":"Alberta","category":"Health","amount":"Monthly premium: $63.50 (single) or $118.00 (family). Subsidized: $44.45 or $82.60.","summary":"Extra health coverage for Albertans under 65 and their dependants. It helps pay for prescriptions, diabetes supplies, ambulance and more. You pay a monthly premium.","note":"From October 1, 2026, private or employer plans pay first. Non-Group Coverage then pays the remaining eligible costs. Lower-income people may get a premium subsidy.","requires":["ab","abBlueCrossNonGroupRoute" ],"eligibility":{"mode":"all","items":["You are an Alberta resident under 65 years old.","You are registered under the Alberta Health Care Insurance Plan (AHCIP).","You pay the monthly premium." ],"note":"Premium subsidy: taxable income under $20,970 (single), $33,240 (family, no children) or $39,250 (with children)."},"applyText":"Open the official page on alberta.ca","applyUrl":"https://www.alberta.ca/non-group-coverage","source":"https://www.alberta.ca/non-group-coverage","detail":{"aboutList":{"lead":"What the plan covers","items":["Prescription drugs on the Alberta Drug Benefit List, with a 30% co-payment up to $35.","Diabetes supplies up to $2,400 a person each benefit year, no co-payment; the limit depends on how diabetes is managed.","Ground ambulance to and from a hospital, up to the rate set by the Alberta government.","Psychologist visits up to $60 each, to $300 per family each year.","Home nursing up to $200 per family each year, with a physician's written order.","A $50 yearly deductible applies to most other benefits." ]},"steps":["Complete the application for Non-Group Coverage.","Send it to the AHCIP office.","To get a lower premium, also complete the Premium Subsidy application and use Line 260 of your tax return." ],"documents":["Line 260 of your federal tax return, and your spouse's or partner's, for the premium subsidy" ],"tips":["Coverage starts the first day of the fourth month after the AHCIP office gets your application.","If you had a plan before, apply within 30 days of its end date. Coverage may start as early as the next month.","You can ask for a subsidy for this benefit year plus two earlier ones.","It does not cover travel. Buy travel insurance for trips outside Alberta.","Albertans 65 and older use the Coverage for Seniors program instead." ],"time":"Coverage starts the first day of the fourth month after the AHCIP office gets your application."}},{"id":"ab-brain-injury","name":"Alberta Brain Injury Initiative","level":"Alberta","category":"Community supports","amount":"Service coordination and help finding supports. No dollar amount is published.","summary":"A network of agencies that helps adults with an acquired brain injury, and their families, find and use supports. A service coordinator looks at your needs and helps build a plan.","note":"Each agency serves set communities. Check the list on the official page to find the one that covers where you live.","requires":["ab","age18plus","brainInjuryDisability","abBrainInjuryRoute" ],"eligibility":{"mode":"all","items":["You are an adult with an acquired brain injury." ],"note":"Families of survivors can also get help from the service coordinators."},"applyText":"Open the official page on alberta.ca","applyUrl":"https://www.alberta.ca/brain-injury-supports","source":"https://www.alberta.ca/brain-injury-supports","detail":{"aboutList":{"lead":"A service coordinator can","items":["Give you information about brain injury and the supports that exist.","Assess what you need.","Work with you, your family and service providers on service plans and agreements.","Refer you to community supports and independent living skills development.","Help you find, apply for and coordinate benefits and services." ]},"steps":["Find the agency that serves your community on the official page.","Contact it by phone or email." ],"documents":[ ],"tips":["The Brain Injury Survival Guide is for survivors and families. Ask your regional agency for a printed copy.","The page also links to free brain injury videos on YouTube." ]}},{"id":"ab-child-family-benefit","name":"Alberta Child and Family Benefit","level":"Alberta","category":"Money (for parents)","amount":"Base: up to $1,529 (1 child) to $3,821 (4 or more), July 2026 to June 2027. Working part: up to $782 to $2,061.","summary":"Payments for lower and middle-income families with children under 18. Getting AISH, Income Support or the Alberta child care subsidy does not stop you from getting it.","note":"The Canada Revenue Agency (CRA) pays in August, November, February and May. The amount depends on your family income and how many children you have.","requires":["ab","abChildFamilyBenefitRoute" ],"eligibility":{"mode":"all","items":["You are a parent of one or more children under 18.","You live in Alberta.","You file a tax return.","You meet the income criteria." ],"note":"In 2026–27, amounts are reduced once family net income goes over $28,116 or $47,115."},"applyText":"Open the official page on alberta.ca","applyUrl":"https://www.alberta.ca/alberta-child-and-family-benefit","source":"https://www.alberta.ca/alberta-child-and-family-benefit","detail":{"aboutList":{"lead":"How it works","items":["The base part goes to lower-income families, whether or not they earn employment income.","The working part starts when family employment income is over $2,760.","The working part grows by 15% of each extra dollar earned, up to the maximum.","Payments are not taxable and do not change your AISH or Income Support." ]},"steps":["File your tax return each year.","If you qualify for the Canada Child Benefit, you are considered automatically.","If you have not applied for the Canada Child Benefit, apply for it online." ],"documents":[ ],"tips":["Free tax clinics can prepare tax returns for eligible lower-income Albertans.","Payments under $10 in a quarter may be joined and paid less often.","Use the child and family benefits calculator to estimate your amount. Have your tax return handy.","If your family leaves Alberta, you may have to return money for the months you were away." ],"phone":"Canada Revenue Agency: 1-800-959-2809"}},{"id":"ab-home-care","name":"Home and Community Care (continuing care at home)","level":"Alberta","category":"Home support","amount":"Publicly funded health and personal care. You pay for medications, nutrition products and long-term supplies.","summary":"Health and personal care at home for people of any age, including help with dressing, bathing, meals and wound care. It also offers respite for caregivers.","note":"Services are meant to add to help from family, friends and community, not replace it. Day program clients pay a daily fee.","requires":["ab","abHomeCareRoute" ],"eligibility":{"mode":"all","items":["You live in Alberta.","A professional assessment finds that you have unmet care needs." ],"note":"Age, diagnosis and how long you need support do not decide who can get services."},"applyText":"Open the official page on alberta.ca","applyUrl":"https://www.alberta.ca/about-continuing-care","source":"https://www.alberta.ca/about-continuing-care","detail":{"aboutList":{"lead":"Services can include help with","items":["Dressing, eating and bathing.","Meal preparation and medication administration.","Wound care and respite.","Short-term care after an accident, injury or illness, or long-term care for disease, disability or aging." ]},"steps":["Read how to access continuing care on the official page.","A professional assesses your unmet care needs." ],"documents":[ ],"tips":["Providers are Assisted Living Alberta, contracted providers, or someone you hire under self-managed care.","Programs such as Alberta Aids to Daily Living (AADL) may help pay for basic medical equipment and supplies.","Palliative care coverage may help with drugs, diabetic supplies and ambulance if you are diagnosed as palliative." ]}},{"id":"ab-income-support","name":"Alberta Income Support","level":"Alberta","category":"Income support","amount":"Money for basic needs. The amount depends on your needs, ability to work and family size.","summary":"Money for basic needs like food, clothing and shelter if you cannot pay for them. It can also include health benefits, employment services and help getting child support.","note":"You can work while on Income Support. Only a portion of your earnings is counted when your benefit is worked out.","requires":["ab","age18plus","abIncomeSupportRoute" ],"eligibility":{"mode":"all","items":["You live in Alberta and are at least 18 years old.","You are a Canadian citizen, permanent resident, refugee or refugee claimant.","You cannot pay for your basic needs.","You have no more than $5,000 in RRSPs per adult and $10,000 equity in vehicles.","Your cash and savings are under the liquid asset limit.","You are willing to apply for other income programs, such as Employment Insurance.","You give personal and financial information for everyone in your household.","You will make and follow a plan with your Income Support worker.","You are looking for work, not earning enough, unable to work, or need job training help." ],"note":"Your income must not be more than what you would get from Income Support core benefits."},"applyText":"Apply online with an Alberta.ca account","applyUrl":"https://www.alberta.ca/income-support-how-to-apply","source":"https://www.alberta.ca/income-support-eligibility","detail":{"aboutList":{"lead":"Depending on your needs, you may get money for","items":["Basic expenses like food, clothing and shelter.","Childcare, special diets, and utility connection fees.","Work-related expenses and school expenses for children.","Unexpected emergencies and costs to leave family violence." ]},"steps":["Create an Alberta.ca account. A verified account is recommended.","Gather your documents.","Apply online.","If you cannot apply online, contact your local Alberta Supports Centre to make an appointment." ],"documents":["Identification for you, your spouse or partner, and any dependents","Bank statements for the 60 days before you apply, for all accounts","A medical letter, if you cannot work for medical reasons" ],"tips":["Income Support staff need you to verify your account before they approve your application.","Emergency help for basic needs can be arranged in as little as 2 days. The 24-hour line is 1-866-644-5135.","Ask for an interpreter if you need one to finish the application.","The liquid asset limit is generally three times the core benefit you would get." ],"time":"The process typically takes 2 weeks.","phone":"Alberta Supports Contact Centre: 1-877-644-9992"}},{"id":"ab-rent-assistance-benefit","name":"Rent Assistance Benefit","level":"Alberta","category":"Housing","amount":"The amount is calculated from your household income and local market rent.","summary":"A long-term rent subsidy for Albertans with low income. It is paid directly to tenants and may be renewed each year.","note":"People are given priority based on need. Need looks at factors such as income, assets, number of dependants and your current housing.","requires":["ab","abRentAssistanceBenefitRoute" ],"eligibility":{"mode":"all","items":["Your income is below the local income limit for your community.","You are a Canadian citizen, permanent resident or refugee, or an applicant for refugee or immigrant status." ],"note":"People with a broken private sponsorship and Ukraine evacuees with emergency travel papers can also apply."},"applyText":"Use the Find Housing tool on alberta.ca","applyUrl":"https://www.alberta.ca/rent-assistance","source":"https://www.alberta.ca/rent-assistance","detail":{"aboutList":{"lead":"Benefit features","items":["It is available through most housing management bodies across Alberta.","There is no limit on yearly renewals if you are still eligible." ]},"steps":["Answer a few questions in the Find Housing tool.","Pick a local housing provider that offers a program that suits you.","Contact the provider for a rent assistance application." ],"documents":[ ],"tips":["A separate Temporary Rent Assistance Benefit lasts 2 years. It has extra rules, such as recent work and not getting Income Support, AISH or the Alberta Seniors Benefit.","Housing providers manage the program and choose tenants.","The Private Landlord Rent Supplement is closed. Current recipients move to this benefit when funding ends." ],"phone":"Alberta Supports Contact Centre: 1-877-644-9992"}},{"id":"ab-seniors-benefit","name":"Alberta Seniors Benefit","level":"Alberta","category":"Income support","amount":"Up to $3,946 a year (single) or $5,918 (couple) for homeowners, renters and lodge residents, when income used is $0.","summary":"Monthly money for lower-income seniors 65 and older. The amount depends on your income, where you live and whether you have a partner.","note":"From July 1, 2026, income guidelines are $32,690 or less (single) and $53,800 or less (couple), for people who get full Old Age Security.","requires":["ab","age65plus","abSeniorsBenefitRoute" ],"eligibility":{"mode":"all","items":["You are 65 or older.","You lived in Alberta for at least 3 months right before you apply.","You are a Canadian citizen or permanent resident.","You get the Old Age Security (OAS) pension.","You meet the financial eligibility criteria." ],"note":"If you or your partner chose to delay OAS, you are not eligible."},"applyText":"Apply online or by mail","applyUrl":"https://www.alberta.ca/alberta-seniors-benefit","source":"https://www.alberta.ca/alberta-seniors-benefit","detail":{"aboutList":{"lead":"How your benefit is worked out","items":["It uses your income and your partner's, last calendar year, from your tax return.","It also depends on your residence type and your marital or cohabitation status.","In a continuing care home: up to $12,466 a year for a single senior, or $16,412 for a couple with one partner at home.","Other residence categories get up to $2,749 (single) or $5,496 (couple)." ]},"steps":["Read the Seniors Financial Assistance information booklet.","Apply online, print the form, or call to ask for a form by mail.","Attach your supporting documents.","Send your documents online, by fax or by mail." ],"documents":["Proof of date of birth, unless you are 65 or older and get Old Age Security","A pre-printed void cheque or direct deposit form (optional)","Income estimate form, if your income dropped and you are applying for the first time" ],"tips":["If you apply online with a verified Alberta.ca account, you can skip the supporting documents step.","You may be paid up to 11 months back from the date the program gets your form, but not before age 65.","Tell the program if you move, your marital status changes, your income changes or your OAS changes.","The benefit year runs July 1 to June 30." ],"phone":"Alberta Supports Contact Centre: 1-877-644-9992"}},{"id":"ab-seniors-dental-optical","name":"Dental and Optical Assistance for Seniors","level":"Alberta","category":"Health","amount":"Dental: up to $5,000 every 5 years. Glasses: up to $230 every 3 years.","summary":"Help paying for basic dental care and prescription glasses for lower-income seniors 65 and older. You must first be approved for Seniors Financial Assistance programs.","note":"Dental coverage may not cover the full fees that dentists charge. Ask your dentist to request pre-authorization from Alberta Blue Cross first.","requires":["ab","age65plus","abSeniorsDentalOpticalRoute" ],"eligibility":{"mode":"all","items":["You are 65 or older.","You are an Alberta resident and lived here at least 3 months before applying.","You are a Canadian citizen or admitted to Canada for permanent residence.","You are approved for Seniors Financial Assistance programs.","Your annual income is within the program limits." ],"note":"For 2026–27, coverage needs 2025 total income of $0 to $32,690 (single) or $0 to $65,380 (couple)."},"applyText":"Apply through Seniors Financial Assistance","applyUrl":"https://www.alberta.ca/dental-optical-assistance-seniors","source":"https://www.alberta.ca/dental-optical-assistance-seniors","detail":{"aboutList":{"lead":"What is covered","items":["Dental: exams, x-rays, cleaning, fillings, extractions, root canals, gum treatment and basic dentures.","Not covered: crowns, bridges, braces, implants, fluoride and cosmetic work.","Optical: prescription glasses, sunglasses, lenses, contact lenses, frames and repairs.","Not covered: eye exams, eye surgery, cataract surgery lenses and magnifiers." ]},"steps":["Apply for Seniors Financial Assistance programs. Skip this if you already did.","Show your Alberta health card at the dental or optical office and say you are enrolled.","Ask the office to bill Alberta Blue Cross directly.","If they cannot, pay the bill and send in a reimbursement claim." ],"documents":["Alberta health card","Receipts and a completed claim form, if you claim a reimbursement" ],"tips":["Unused dental money does not carry into the next 5-year period. Unused optical money does not carry into the next 3-year period.","Claim within 12 months of the expense or it will not be paid.","For services covered by both plans, claim from the Canadian Dental Care Plan first.","If cataract surgery changes your prescription, you may get funding for another set of glasses. You need a medical note." ],"phone":"Alberta Blue Cross claims: 1-800-661-6995"}},{"id":"ab-seniors-special-needs-assistance","name":"Special Needs Assistance for Seniors","level":"Alberta","category":"Daily living supports","amount":"Up to $5,872 in a benefit year (July 1 to June 30).","summary":"Money toward set items for lower-income seniors 65 and older, such as CPAP machines, diabetes supplies, prescription costs, clothing, and appliances or furniture.","note":"A receipt or estimate is needed for all requests unless the page says otherwise. Items bought before you enrolled are not covered.","requires":["ab","age65plus","abSeniorsSpecialNeedsAssistanceRoute" ],"eligibility":{"mode":"all","items":["You are 65 or older and an Alberta resident.","You are a Canadian citizen or lawfully admitted for permanent residence.","You have provided a Seniors Financial Assistance application.","You meet the financial criteria.","Neither you nor your spouse has deferred Old Age Security." ],"note":"In general, $32,690 or less (single) or $53,800 or less (couple) may qualify."},"applyText":"Make a claim through MyAlberta Seniors or by mail","applyUrl":"https://www.alberta.ca/seniors-special-needs-assistance","source":"https://www.alberta.ca/seniors-special-needs-assistance","detail":{"aboutList":{"lead":"How income sets what you can get","items":["Single with income of $28,290 or less: primary and secondary items.","Single with income of $28,291 to $32,690: primary items only.","Couple with income of $45,600 or less: primary and secondary items.","Couple with income of $45,601 to $53,800: primary items only.","Examples: CPAP up to $1,881 every 5 years, celiac groceries up to $63 a month, refrigerator up to $824 (one time only)." ]},"steps":["Enrol in Seniors Financial Assistance programs if you have not.","Get a receipt or estimate with your name, Personal Health Number, address and phone number.","Add any medical notes the item needs.","Send your claim through MyAlberta Seniors, or by mail or fax." ],"documents":["Receipt or estimate for each item","Medical notes for items that need them" ],"tips":["The program accepts a receipt for an item bought up to 12 months before it gets your claim.","You must have been eligible when you bought the item.","Keep receipts for funded items for at least 2 years.","You can appeal a decision. The page lists the steps." ],"phone":"Alberta Supports Contact Centre: 1-877-644-9992"}},{"id":"ab-sharp","name":"Seniors Home Adaptation and Repair Program (SHARP)","level":"Alberta","category":"Home","amount":"A low-interest loan of $500 to $40,000. The current interest rate is 4.45%.","summary":"A low-interest home equity loan for seniors to repair or adapt their home, such as stair lifts, walk-in tubs or wider doorways. You do not make monthly repayments.","note":"The loan is due when you sell, are no longer a registered owner, or the home is no longer your main home. The government registers a caveat on your land title.","requires":["ab","age65plus","abSharpRoute" ],"eligibility":{"mode":"all","items":["You are 65 or older. Only one spouse or partner needs to be 65 or older.","You are a registered owner of a home in a Land Titles Office.","Your annual income is $75,000 or less.","You keep at least 25% equity in your main home after the loan.","You are a Canadian citizen or lawfully admitted for permanent residence.","You have lived in Alberta for at least 3 months." ],"note":"Your income is taken from line 15000 of last year's tax return."},"applyText":"Apply with the Loan Application and Agreement","applyUrl":"https://www.alberta.ca/seniors-home-adaptation-repair-program","source":"https://www.alberta.ca/seniors-home-adaptation-repair-program","detail":{"aboutList":{"lead":"What the loan can pay for","items":["Repairs, adaptations and renovations to your main home.","Projects that help you stay safe, independent and mobile, or improve energy efficiency.","Work paid for in the 12 months before the program gets your application." ]},"steps":["Read the information guide.","Complete and sign the Loan Application and Agreement.","Send it with your supporting documents online, by fax or by mail." ],"documents":["A written cost estimate or receipts for all project costs","Property tax assessment or bill","Direct deposit form or void cheque (optional)" ],"tips":["If you do not qualify for a loan, a single senior with income of $32,690 or less, or a couple with $53,800 or less, may be considered for a grant.","Charges such as a reverse mortgage, bankruptcy or foreclosure on your land title must be removed first.","If you sign a repair contract, apply within 45 days to keep your cancellation rights.","Interest is simple interest and is reviewed in April and October." ],"phone":"Alberta Supports Contact Centre (ask for a call back from a loan specialist): 1-877-644-9992"}} ]);
